-- Name: get_available_stock(uuid, uuid); Type: FUNCTION; Schema: inventory; Owner: postgres
--

CREATE FUNCTION inventory.get_available_stock(p_variant_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS TABLE(warehouse_id uuid, warehouse_code character varying, location_id uuid, location_code character varying, quantity_on_hand numeric, quantity_reserved numeric, safety_stock numeric, available_to_sell numeric)
    LANGUAGE sql STABLE
    AS $$
SELECT
    w.warehouse_id,
    w.warehouse_code,
    l.location_id,
    l.location_code,
    i.quantity_on_hand,
    i.quantity_reserved,
    i.safety_stock,
    GREATEST(0, i.quantity_on_hand - i.quantity_reserved - i.safety_stock) AS available_to_sell
FROM inventory.inventories i
JOIN inventory.warehouses w ON w.warehouse_id = i.warehouse_id
JOIN inventory.warehouse_locations l ON l.location_id = i.location_id
JOIN inventory.location_type_lookup lt ON lt.location_type_id = l.location_type_id
WHERE i.variant_id = p_variant_id
  AND (p_warehouse_id IS NULL OR i.warehouse_id = p_warehouse_id)
  AND lt.is_sellable = TRUE
  AND l.is_active = TRUE
  AND w.is_active = TRUE
ORDER BY w.warehouse_code, l.location_code;
$$;


ALTER FUNCTION inventory.get_available_stock(p_variant_id uuid, p_warehouse_id uuid) OWNER TO postgres;

