CREATE FUNCTION inventory.get_cost_layers(p_variant_id uuid, p_warehouse_id uuid) RETURNS TABLE(cost_layer_id uuid, source_type_code character varying, source_type_name character varying, source_reference_type character varying, source_reference_id uuid, quantity_received numeric, quantity_remaining numeric, unit_cost numeric, layer_value numeric, received_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
SELECT
    cl.cost_layer_id,
    cst.code AS source_type_code,
    cst.name AS source_type_name,
    cl.source_reference_type,
    cl.source_reference_id,
    cl.quantity_received,
    cl.quantity_remaining,
    cl.unit_cost,
    cl.quantity_remaining * cl.unit_cost AS layer_value,
    cl.received_at
FROM inventory.inventory_cost_layers cl
JOIN inventory.cost_source_type_lookup cst ON cst.cost_source_type_id = cl.source_type_id
WHERE cl.variant_id = p_variant_id
  AND cl.warehouse_id = p_warehouse_id
  AND cl.quantity_remaining > 0
ORDER BY cl.received_at;
$$;


ALTER FUNCTION inventory.get_cost_layers(p_variant_id uuid, p_warehouse_id uuid) OWNER TO postgres;

--
-- TOC entry 965 (class 1255 OID 110755)
-- Name: get_inventory_value(uuid); Type: FUNCTION; Schema: inventory; Owner: postgres
--

CREATE FUNCTION inventory.get_inventory_value(p_company_id uuid) RETURNS TABLE(warehouse_code character varying, warehouse_name character varying, total_units numeric, total_cost_value numeric, weighted_average_cost numeric)
    LANGUAGE sql STABLE
    AS $$
SELECT
    iv.warehouse_code,
    iv.warehouse_name,
    SUM(iv.total_on_hand) AS total_units,
    SUM(iv.total_cost_value) AS total_cost_value,
    CASE
        WHEN SUM(iv.total_on_hand) > 0
        THEN SUM(iv.total_cost_value) / SUM(iv.total_on_hand)
        ELSE 0
    END AS weighted_average_cost
FROM inventory.read_inventory_valuation iv
WHERE iv.company_id = p_company_id
GROUP BY iv.warehouse_code, iv.warehouse_name
ORDER BY iv.warehouse_code;
$$;


ALTER FUNCTION inventory.get_inventory_value(p_company_id uuid) OWNER TO postgres;

