--
-- TOC entry 923 (class 1255 OID 110751)
-- Name: get_stock(uuid, uuid); Type: FUNCTION; Schema: inventory; Owner: postgres
--

CREATE FUNCTION inventory.get_stock(p_variant_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS TABLE(warehouse_id uuid, warehouse_code character varying, warehouse_name character varying, location_id uuid, location_code character varying, location_name character varying, location_type_code character varying, is_sellable boolean, quantity_on_hand numeric, quantity_reserved numeric, safety_stock numeric, available numeric, available_to_sell numeric)
    LANGUAGE sql STABLE
    AS $$
SELECT
    w.warehouse_id,
    w.warehouse_code,
    w.warehouse_name,
    l.location_id,
    l.location_code,
    l.location_name,
    lt.code AS location_type_code,
    lt.is_sellable,
    i.quantity_on_hand,
    i.quantity_reserved,
    i.safety_stock,
    GREATEST(0, i.quantity_on_hand - i.quantity_reserved) AS available,
    GREATEST(0, i.quantity_on_hand - i.quantity_reserved - i.safety_stock) AS available_to_sell
FROM inventory.inventories i
JOIN inventory.warehouses w ON w.warehouse_id = i.warehouse_id
JOIN inventory.warehouse_locations l ON l.location_id = i.location_id
JOIN inventory.location_type_lookup lt ON lt.location_type_id = l.location_type_id
WHERE i.variant_id = p_variant_id
  AND (p_warehouse_id IS NULL OR i.warehouse_id = p_warehouse_id)
  AND w.is_active = TRUE
  AND l.is_active = TRUE
ORDER BY w.warehouse_code, l.location_code;
$$;


ALTER FUNCTION inventory.get_stock(p_variant_id uuid, p_warehouse_id uuid) OWNER TO postgres;

--
-- TOC entry 1033 (class 1255 OID 110752)
-- Name: get_stock_summary(uuid); Type: FUNCTION; Schema: inventory; Owner: postgres
--

CREATE FUNCTION inventory.get_stock_summary(p_variant_id uuid) RETURNS TABLE(total_on_hand numeric, total_reserved numeric, total_safety_stock numeric, total_available numeric, total_available_to_sell numeric, warehouse_count bigint, location_count bigint)
    LANGUAGE sql STABLE
    AS $$
SELECT
    COALESCE(SUM(i.quantity_on_hand), 0) AS total_on_hand,
    COALESCE(SUM(i.quantity_reserved), 0) AS total_reserved,
    COALESCE(SUM(i.safety_stock), 0) AS total_safety_stock,
    GREATEST(0, COALESCE(SUM(i.quantity_on_hand), 0) - COALESCE(SUM(i.quantity_reserved), 0)) AS total_available,
    GREATEST(0, COALESCE(SUM(i.quantity_on_hand), 0) - COALESCE(SUM(i.quantity_reserved), 0) - COALESCE(SUM(i.safety_stock), 0)) AS total_available_to_sell,
    COUNT(DISTINCT i.warehouse_id) AS warehouse_count,
    COUNT(DISTINCT i.location_id) AS location_count
FROM inventory.inventories i
JOIN inventory.warehouses w ON w.warehouse_id = i.warehouse_id
JOIN inventory.warehouse_locations l ON l.location_id = i.location_id
JOIN inventory.location_type_lookup lt ON lt.location_type_id = l.location_type_id
WHERE i.variant_id = p_variant_id
  AND w.is_active = TRUE
  AND l.is_active = TRUE
  AND lt.is_sellable = TRUE;
$$;


ALTER FUNCTION inventory.get_stock_summary(p_variant_id uuid) OWNER TO postgres;

--
-- TOC entry 924 (class 1255 OID 109808)
-- Name: get_applicable_discount_rules(uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: pricing; Owner: postgres
--

CREATE FUNCTION pricing.get_applicable_discount_rules(p_company_id uuid, p_product_id uuid, p_customer_segment_id uuid DEFAULT NULL::uuid, p_sales_channel_id uuid DEFAULT NULL::uuid, p_business_unit_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP) RETURNS TABLE(discount_rule_id uuid, campaign_id uuid, campaign_code character varying, campaign_name character varying, discount_type_code character varying, discount_value numeric, maximum_discount_amount numeric, minimum_order_amount numeric, minimum_quantity integer, priority integer, is_stackable boolean)
    LANGUAGE sql STABLE
    AS $$
WITH product_info AS
(
    SELECT
        p.product_id,
        p.company_id,
        p.brand_id,
        p.product_type_id
    FROM catalog.products p
    WHERE p.product_id = p_product_id
)
SELECT
    dr.discount_rule_id,
    c.campaign_id,
    c.campaign_code,
    c.campaign_name,
    dt.code AS discount_type_code,
    dr.discount_value,
    dr.maximum_discount_amount,
    dr.minimum_order_amount,
    dr.minimum_quantity,
    dr.priority,
    dr.is_stackable
FROM pricing.discount_rules dr
JOIN pricing.campaigns c
  ON c.campaign_id = dr.campaign_id
 AND c.company_id = p_company_id
JOIN pricing.discount_type_lookup dt
  ON dt.discount_type_id = dr.discount_type_id
WHERE c.is_active = TRUE
  AND c.status_code = 'ACTIVE'
  AND c.start_date <= p_at
  AND c.end_date >= p_at
  AND (c.sales_channel_id IS NULL OR c.sales_channel_id = p_sales_channel_id)
  AND (c.business_unit_id IS NULL OR c.business_unit_id = p_business_unit_id)
  AND dr.is_active = TRUE
  AND (dr.start_date IS NULL OR dr.start_date <= p_at)
  AND (dr.end_date IS NULL OR dr.end_date >= p_at)
  AND (
        -- No targeting means store-wide rule.
        (
            NOT EXISTS (SELECT 1 FROM pricing.discount_rule_products x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_categories x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_brands x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_collections x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_product_types x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_customer_segments x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_sales_channels x WHERE x.discount_rule_id = dr.discount_rule_id)
            AND NOT EXISTS (SELECT 1 FROM pricing.discount_rule_business_units x WHERE x.discount_rule_id = dr.discount_rule_id)
        )
        OR EXISTS
        (
            SELECT 1
            FROM pricing.discount_rule_products dp
            WHERE dp.discount_rule_id = dr.discount_rule_id
              AND dp.product_id = p_product_id
        )
        OR EXISTS
        (
            SELECT 1
            FROM pricing.discount_rule_categories dc
            JOIN catalog.product_categories pc
              ON pc.category_id = dc.category_id
            WHERE dc.discount_rule_id = dr.discount_rule_id
              AND pc.product_id = p_product_id
        )
        OR EXISTS
        (
            SELECT 1
            FROM pricing.discount_rule_brands db
            JOIN product_info pi
              ON pi.brand_id = db.brand_id
            WHERE db.discount_rule_id = dr.discount_rule_id
              AND pi.product_id = p_product_id
        )
        OR EXISTS
        (
            SELECT 1
            FROM pricing.discount_rule_collections dcol
            JOIN catalog.collection_products cp
              ON cp.collection_id = dcol.collection_id
            WHERE dcol.discount_rule_id = dr.discount_rule_id
              AND cp.product_id = p_product_id
        )
        OR EXISTS
        (
            SELECT 1
            FROM pricing.discount_rule_product_types dpt
            JOIN product_info pi
              ON pi.product_type_id = dpt.product_type_id
            WHERE dpt.discount_rule_id = dr.discount_rule_id
              AND pi.product_id = p_product_id
        )
        OR (
            p_customer_segment_id IS NOT NULL
            AND EXISTS
            (
                SELECT 1
                FROM pricing.discount_rule_customer_segments ds
                WHERE ds.discount_rule_id = dr.discount_rule_id
                  AND ds.customer_segment_id = p_customer_segment_id
            )
        )
        OR (
            p_sales_channel_id IS NOT NULL
            AND EXISTS
            (
                SELECT 1
                FROM pricing.discount_rule_sales_channels dsc
                WHERE dsc.discount_rule_id = dr.discount_rule_id
                  AND dsc.sales_channel_id = p_sales_channel_id
            )
        )
        OR (
            p_business_unit_id IS NOT NULL
            AND EXISTS
            (
                SELECT 1
                FROM pricing.discount_rule_business_units dbu
                WHERE dbu.discount_rule_id = dr.discount_rule_id
                  AND dbu.business_unit_id = p_business_unit_id
            )
        )
  )
ORDER BY
    dr.priority DESC,
    c.priority DESC,
    c.campaign_code,
    dr.rule_name;
$$;


ALTER FUNCTION pricing.get_applicable_discount_rules(p_company_id uuid, p_product_id uuid, p_customer_segment_id uuid, p_sales_channel_id uuid, p_business_unit_id uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 1020 (class 1255 OID 109476)
-- Name: get_applicable_tax_rates(uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: pricing; Owner: postgres
--

CREATE FUNCTION pricing.get_applicable_tax_rates(p_company_id uuid, p_product_id uuid, p_country_id uuid, p_state_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP) RETURNS TABLE(tax_rule_id uuid, rule_name character varying, rule_priority integer, tax_rate_id uuid, tax_type_code character varying, tax_type_name character varying, tax_category_code character varying, rate numeric, is_inclusive boolean, sequence integer)
    LANGUAGE sql STABLE
    AS $$
WITH product_tax_category AS
(
    SELECT ptc.tax_category_id
    FROM pricing.product_tax_categories ptc
    WHERE ptc.product_id = p_product_id
      AND ptc.is_active = TRUE
      AND (ptc.start_date IS NULL OR ptc.start_date <= p_at)
      AND (ptc.end_date IS NULL OR ptc.end_date >= p_at)
    ORDER BY ptc.start_date DESC NULLS LAST
    LIMIT 1
),
matching_rules AS
(
    SELECT tr.*
    FROM pricing.tax_rules tr
    WHERE tr.company_id = p_company_id
      AND tr.is_active = TRUE
      AND (tr.start_date IS NULL OR tr.start_date <= p_at)
      AND (tr.end_date IS NULL OR tr.end_date >= p_at)
      AND (tr.country_id IS NULL OR tr.country_id = p_country_id)
      AND (tr.state_id IS NULL OR tr.state_id = p_state_id)
      AND (
            tr.tax_category_id IS NULL
            OR tr.tax_category_id = (SELECT tax_category_id FROM product_tax_category)
          )
      AND (
            tr.product_type_id IS NULL
            OR EXISTS
            (
                SELECT 1
                FROM catalog.products p
                WHERE p.product_id = p_product_id
                  AND p.product_type_id = tr.product_type_id
            )
          )
      AND (
            tr.product_category_id IS NULL
            OR EXISTS
            (
                SELECT 1
                FROM catalog.product_categories pc
                WHERE pc.product_id = p_product_id
                  AND pc.category_id = tr.product_category_id
            )
          )
)
SELECT
    mr.tax_rule_id,
    mr.rule_name,
    mr.priority AS rule_priority,
    trt.tax_rate_id,
    tt.code AS tax_type_code,
    tt.name AS tax_type_name,
    tc.code AS tax_category_code,
    tr.rate,
    tr.is_inclusive,
    trt.sequence
FROM matching_rules mr
JOIN pricing.tax_rule_taxes trt
  ON trt.tax_rule_id = mr.tax_rule_id
JOIN pricing.tax_rates tr
  ON tr.tax_rate_id = trt.tax_rate_id
JOIN pricing.tax_types tt
  ON tt.tax_type_id = tr.tax_type_id
LEFT JOIN pricing.tax_categories tc
  ON tc.tax_category_id = tr.tax_category_id
WHERE tr.is_active = TRUE
  AND (tr.start_date IS NULL OR tr.start_date <= p_at)
  AND (tr.end_date IS NULL OR tr.end_date >= p_at)
  AND (tr.country_id IS NULL OR tr.country_id = p_country_id)
  AND (tr.state_id IS NULL OR tr.state_id = p_state_id)
ORDER BY
    mr.priority DESC,
    mr.rule_name,
    trt.sequence;
$$;


ALTER FUNCTION pricing.get_applicable_tax_rates(p_company_id uuid, p_product_id uuid, p_country_id uuid, p_state_id uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 987 (class 1255 OID 185151)
-- Name: calculate_product_margin(uuid); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.calculate_product_margin(p_variant_id uuid) RETURNS TABLE(variant_code character varying, selling_price numeric, cost_price numeric, margin_amount numeric, margin_percent numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT v.variant_code, pr.unit_price,
           COALESCE((SELECT icl.unit_cost FROM inventory.inventory_cost_layers icl
                     WHERE icl.variant_id = v.variant_id ORDER BY icl.received_at DESC, icl.created_at DESC LIMIT 1), 0),
           (pr.unit_price - COALESCE((SELECT icl.unit_cost FROM inventory.inventory_cost_layers icl
                     WHERE icl.variant_id = v.variant_id ORDER BY icl.received_at DESC, icl.created_at DESC LIMIT 1), 0)),
           CASE WHEN pr.unit_price > 0 THEN ROUND(((pr.unit_price - COALESCE((SELECT icl.unit_cost FROM inventory.inventory_cost_layers icl
                     WHERE icl.variant_id = v.variant_id ORDER BY icl.received_at DESC, icl.created_at DESC LIMIT 1), 0)) / pr.unit_price * 100)::numeric, 2) ELSE 0 END
    FROM catalog.product_variants v LEFT JOIN pricing.prices pr ON pr.variant_id = v.variant_id AND pr.is_active = TRUE
    WHERE v.variant_id = p_variant_id;
END;
$$;


ALTER FUNCTION reports.calculate_product_margin(p_variant_id uuid) OWNER TO postgres;

--
-- TOC entry 1057 (class 1255 OID 185316)
-- Name: check_expense_policy(uuid); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.check_expense_policy(p_expense_claim_item_id uuid) RETURNS TABLE(violation_found boolean, violation_type character varying, expected_value numeric, actual_value numeric, severity character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item RECORD;
    v_policy_rule RECORD;
BEGIN
    SELECT eci.*, ec.company_id INTO v_item
    FROM expenses.expense_claim_items eci
    JOIN expenses.expense_claims ec ON ec.expense_claim_id = eci.expense_claim_id
    WHERE eci.expense_claim_item_id = p_expense_claim_item_id;

    IF v_item IS NULL THEN
        RETURN QUERY SELECT FALSE, 'ITEM_NOT_FOUND'::VARCHAR, NULL::NUMERIC, NULL::NUMERIC, 'LOW'::VARCHAR;
        RETURN;
    END IF;

    FOR v_policy_rule IN
        SELECT epr.*
        FROM expenses.expense_policy_rules epr
        JOIN expenses.expense_policies ep ON ep.expense_policy_id = epr.expense_policy_id
        WHERE ep.company_id = v_item.company_id
          AND ep.is_active = TRUE
          AND (epr.expense_category_id IS NULL OR epr.expense_category_id = v_item.expense_category_id)
    LOOP
        IF v_policy_rule.maximum_amount IS NOT NULL AND v_item.amount > v_policy_rule.maximum_amount THEN
            RETURN QUERY SELECT TRUE, 'AMOUNT_LIMIT_EXCEEDED'::VARCHAR, v_policy_rule.maximum_amount, v_item.amount, 'HIGH'::VARCHAR;
            RETURN;
        END IF;
    END LOOP;

    RETURN QUERY SELECT FALSE, 'NO_VIOLATION'::VARCHAR, NULL::NUMERIC, NULL::NUMERIC, 'LOW'::VARCHAR;
END;
$$;


ALTER FUNCTION reports.check_expense_policy(p_expense_claim_item_id uuid) OWNER TO postgres;

--
-- TOC entry 1061 (class 1255 OID 185317)
-- Name: detect_duplicate_expense(uuid); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.detect_duplicate_expense(p_expense_claim_item_id uuid) RETURNS TABLE(is_duplicate boolean, duplicate_count bigint, matching_items text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item RECORD;
    v_count BIGINT;
BEGIN
    SELECT eci.* INTO v_item
    FROM expenses.expense_claim_items eci
    WHERE eci.expense_claim_item_id = p_expense_claim_item_id;

    IF v_item IS NULL THEN
        RETURN QUERY SELECT FALSE, 0::BIGINT, 'Item not found'::TEXT;
        RETURN;
    END IF;

    SELECT COUNT(*) INTO v_count
    FROM expenses.expense_claim_items eci2
    WHERE eci2.expense_claim_item_id <> p_expense_claim_item_id
      AND eci2.expense_date = v_item.expense_date
      AND eci2.amount = v_item.amount
      AND (eci2.merchant_name = v_item.merchant_name OR (eci2.merchant_name IS NULL AND v_item.merchant_name IS NULL));

    RETURN QUERY SELECT v_count > 0, v_count,
        CASE WHEN v_count > 0 THEN 'Potential duplicate found' ELSE 'No duplicates detected' END;
END;
$$;


ALTER FUNCTION reports.detect_duplicate_expense(p_expense_claim_item_id uuid) OWNER TO postgres;

