--
-- TOC entry 1041 (class 1255 OID 185315)
-- Name: get_budget_utilization(uuid, uuid); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_budget_utilization(p_company_id uuid, p_fiscal_year_id uuid DEFAULT NULL::uuid) RETURNS TABLE(department_name character varying, category_name character varying, budget_amount numeric, actual_amount numeric, utilization_percent numeric, remaining numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        d.department_name,
        ecat.name,
        eb.budget_amount,
        COALESCE(SUM(ebp.actual_amount), 0),
        CASE WHEN eb.budget_amount > 0
            THEN ROUND((COALESCE(SUM(ebp.actual_amount), 0) / eb.budget_amount * 100)::numeric, 2)
            ELSE 0 END,
        eb.budget_amount - COALESCE(SUM(ebp.actual_amount), 0)
    FROM expenses.expense_budgets eb
    LEFT JOIN expenses.expense_budget_periods ebp ON ebp.expense_budget_id = eb.expense_budget_id
    LEFT JOIN organization.departments d ON d.department_id = eb.department_id
    LEFT JOIN expenses.expense_categories ecat ON ecat.expense_category_id = eb.expense_category_id
    WHERE eb.company_id = p_company_id
      AND (p_fiscal_year_id IS NULL OR eb.fiscal_year_id = p_fiscal_year_id)
    GROUP BY eb.expense_budget_id, d.department_name, ecat.name, eb.budget_amount
    ORDER BY utilization_percent DESC;
END;
$$;


ALTER FUNCTION reports.get_budget_utilization(p_company_id uuid, p_fiscal_year_id uuid) OWNER TO postgres;

--
-- TOC entry 955 (class 1255 OID 185321)
-- Name: get_category_expense_breakdown(uuid, date, date); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_category_expense_breakdown(p_company_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(category_code character varying, category_name character varying, parent_category character varying, transaction_count bigint, total_amount numeric, percent_of_total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total NUMERIC;
BEGIN
    SELECT SUM(eci.amount) INTO v_total
    FROM expenses.expense_claim_items eci
    JOIN expenses.expense_claims ec ON ec.expense_claim_id = eci.expense_claim_id
    WHERE ec.company_id = p_company_id
      AND ec.claim_date BETWEEN p_start_date AND p_end_date
      AND ec.status NOT IN ('DRAFT', 'CANCELLED');

    RETURN QUERY
    SELECT
        ecat.code,
        ecat.name,
        pcat.name,
        COUNT(DISTINCT eci.expense_claim_item_id),
        SUM(eci.amount),
        CASE WHEN v_total > 0 THEN ROUND((SUM(eci.amount) / v_total * 100)::numeric, 2) ELSE 0 END
    FROM expenses.expense_claim_items eci
    JOIN expenses.expense_categories ecat ON ecat.expense_category_id = eci.expense_category_id
    LEFT JOIN expenses.expense_categories pcat ON pcat.expense_category_id = ecat.parent_category_id
    JOIN expenses.expense_claims ec ON ec.expense_claim_id = eci.expense_claim_id
    WHERE ec.company_id = p_company_id
      AND ec.claim_date BETWEEN p_start_date AND p_end_date
      AND ec.status NOT IN ('DRAFT', 'CANCELLED')
    GROUP BY ecat.code, ecat.name, pcat.name
    ORDER BY SUM(eci.amount) DESC;
END;
$$;


ALTER FUNCTION reports.get_category_expense_breakdown(p_company_id uuid, p_start_date date, p_end_date date) OWNER TO postgres;

--
-- TOC entry 1042 (class 1255 OID 185314)
-- Name: get_department_expense_report(uuid, date, date); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_department_expense_report(p_department_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(department_name character varying, claim_count bigint, total_amount numeric, approved_amount numeric, top_category character varying, top_category_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        d.department_name,
        COUNT(DISTINCT ec.expense_claim_id),
        SUM(ec.total_amount),
        SUM(COALESCE(ec.approved_amount, 0)),
        (SELECT ecat.name FROM expenses.expense_claim_items eci2
         JOIN expenses.expense_categories ecat ON ecat.expense_category_id = eci2.expense_category_id
         JOIN expenses.expense_claims ec2 ON ec2.expense_claim_id = eci2.expense_claim_id
         WHERE ec2.department_id = p_department_id
         GROUP BY ecat.name ORDER BY SUM(eci2.amount) DESC LIMIT 1),
        (SELECT SUM(eci3.amount) FROM expenses.expense_claim_items eci3
         JOIN expenses.expense_categories ecat2 ON ecat2.expense_category_id = eci3.expense_category_id
         JOIN expenses.expense_claims ec3 ON ec3.expense_claim_id = eci3.expense_claim_id
         WHERE ec3.department_id = p_department_id
         GROUP BY ecat2.name ORDER BY SUM(eci3.amount) DESC LIMIT 1)
    FROM expenses.expense_claims ec
    JOIN organization.departments d ON d.department_id = ec.department_id
    WHERE ec.department_id = p_department_id
      AND ec.claim_date BETWEEN p_start_date AND p_end_date
      AND ec.status NOT IN ('DRAFT', 'CANCELLED')
    GROUP BY d.department_name;
END;
$$;


ALTER FUNCTION reports.get_department_expense_report(p_department_id uuid, p_start_date date, p_end_date date) OWNER TO postgres;

--
-- TOC entry 926 (class 1255 OID 185313)
-- Name: get_employee_expense_report(uuid, date, date); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_employee_expense_report(p_employee_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(claim_number character varying, claim_date date, status character varying, total_amount numeric, approved_amount numeric, item_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ec.claim_number,
        ec.claim_date,
        ec.status,
        ec.total_amount,
        ec.approved_amount,
        COUNT(DISTINCT eci.expense_claim_item_id)
    FROM expenses.expense_claims ec
    LEFT JOIN expenses.expense_claim_items eci ON eci.expense_claim_id = ec.expense_claim_id
    WHERE ec.employee_id = p_employee_id
      AND ec.claim_date BETWEEN p_start_date AND p_end_date
    GROUP BY ec.expense_claim_id, ec.claim_number, ec.claim_date, ec.status, ec.total_amount, ec.approved_amount
    ORDER BY ec.claim_date DESC;
END;
$$;


