--
-- TOC entry 973 (class 1255 OID 185312)
-- Name: get_expense_summary(uuid, date, date); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_expense_summary(p_company_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(total_claims bigint, total_amount numeric, approved_amount numeric, reimbursed_amount numeric, pending_count bigint, avg_claim_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(DISTINCT ec.expense_claim_id),
        SUM(ec.total_amount),
        SUM(COALESCE(ec.approved_amount, 0)),
        SUM(COALESCE(ec.reimbursed_amount, 0)),
        COUNT(DISTINCT CASE WHEN ec.status IN ('SUBMITTED', 'UNDER_REVIEW') THEN ec.expense_claim_id END),
        ROUND(AVG(ec.total_amount)::numeric, 2)
    FROM expenses.expense_claims ec
    WHERE ec.company_id = p_company_id
      AND ec.claim_date BETWEEN p_start_date AND p_end_date
      AND ec.status NOT IN ('DRAFT', 'CANCELLED');
END;
$$;


ALTER FUNCTION reports.get_expense_summary(p_company_id uuid, p_start_date date, p_end_date date) OWNER TO postgres;

--
-- TOC entry 1052 (class 1255 OID 185319)
-- Name: get_expense_trend(uuid, integer); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_expense_trend(p_company_id uuid, p_months integer DEFAULT 12) RETURNS TABLE(expense_month date, claim_count bigint, total_amount numeric, avg_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        DATE_TRUNC('month', ec.claim_date)::DATE,
        COUNT(DISTINCT ec.expense_claim_id),
        SUM(ec.total_amount),
        ROUND(AVG(ec.total_amount)::numeric, 2)
    FROM expenses.expense_claims ec
    WHERE ec.company_id = p_company_id
      AND ec.claim_date >= CURRENT_DATE - (p_months || ' months')::INTERVAL
      AND ec.status NOT IN ('DRAFT', 'CANCELLED')
    GROUP BY DATE_TRUNC('month', ec.claim_date)
    ORDER BY expense_month DESC;
END;
$$;


ALTER FUNCTION reports.get_expense_trend(p_company_id uuid, p_months integer) OWNER TO postgres;

--
-- TOC entry 972 (class 1255 OID 185320)
-- Name: get_outstanding_reimbursements(uuid); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_outstanding_reimbursements(p_company_id uuid) RETURNS TABLE(reimbursement_number character varying, employee_id uuid, requested_amount numeric, approved_amount numeric, paid_amount numeric, outstanding numeric, days_outstanding integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        er.reimbursement_number,
        er.employee_id,
        er.requested_amount,
        er.approved_amount,
        er.paid_amount,
        COALESCE(er.approved_amount, er.requested_amount) - COALESCE(er.paid_amount, 0),
        (CURRENT_DATE - er.created_at::DATE)
    FROM expenses.expense_reimbursements er
    WHERE er.company_id = p_company_id
      AND er.status IN ('APPROVED', 'PROCESSING', 'PARTIALLY_PAID')
    ORDER BY days_outstanding DESC;
END;
$$;


ALTER FUNCTION reports.get_outstanding_reimbursements(p_company_id uuid) OWNER TO postgres;

--
-- TOC entry 937 (class 1255 OID 185318)
-- Name: get_petty_cash_reconciliation(uuid); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_petty_cash_reconciliation(p_petty_cash_account_id uuid) RETURNS TABLE(opening_balance numeric, total_cash_in numeric, total_expenses numeric, total_cash_out numeric, expected_balance numeric, current_balance numeric, difference numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_account RECORD;
    v_in NUMERIC;
    v_out NUMERIC;
BEGIN
    SELECT * INTO v_account FROM expenses.petty_cash_accounts WHERE petty_cash_account_id = p_petty_cash_account_id;

    SELECT COALESCE(SUM(amount), 0) INTO v_in
    FROM expenses.petty_cash_transactions
    WHERE petty_cash_account_id = p_petty_cash_account_id
      AND transaction_type IN ('CASH_IN', 'REPLENISHMENT', 'OPENING_BALANCE');

    SELECT COALESCE(SUM(ABS(amount)), 0) INTO v_out
    FROM expenses.petty_cash_transactions
    WHERE petty_cash_account_id = p_petty_cash_account_id
      AND transaction_type IN ('EXPENSE', 'CASH_OUT', 'ADJUSTMENT');

    RETURN QUERY SELECT
        v_account.opening_balance,
        v_in,
        v_out,
        0::NUMERIC,
        v_account.opening_balance + v_in - v_out,
        v_account.current_balance,
        v_account.current_balance - (v_account.opening_balance + v_in - v_out);
END;
$$;


ALTER FUNCTION reports.get_petty_cash_reconciliation(p_petty_cash_account_id uuid) OWNER TO postgres;

--
-- TOC entry 984 (class 1255 OID 185140)
-- Name: get_product_sales_performance(uuid, date, date); Type: FUNCTION; Schema: reports; Owner: postgres
--

CREATE FUNCTION reports.get_product_sales_performance(p_product_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(product_name character varying, total_quantity_sold numeric, total_revenue numeric, avg_order_value numeric, order_count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT p.product_name, SUM(oi.quantity), SUM(oi.final_amount), AVG(oi.final_amount / oi.quantity), COUNT(DISTINCT oi.order_id)
    FROM sales.order_items oi
    JOIN catalog.product_variants v ON v.variant_id = oi.variant_id
    JOIN catalog.products p ON p.product_id = v.product_id
    JOIN sales.orders o ON o.order_id = oi.order_id
    WHERE p.product_id = p_product_id AND o.order_date BETWEEN p_start_date AND p_end_date
    GROUP BY p.product_name;
END;
$$;


ALTER FUNCTION reports.get_product_sales_performance(p_product_id uuid, p_start_date date, p_end_date date) OWNER TO postgres;

