--
-- TOC entry 771 (class 1259 OID 118432)
-- Name: view_balance_sheet; Type: VIEW; Schema: accounting; Owner: postgres
--

CREATE VIEW accounting.view_balance_sheet AS
 SELECT at.code AS category,
        CASE
            WHEN ((at.code)::text = 'ASSET'::text) THEN 'Assets'::character varying
            WHEN ((at.code)::text = 'LIABILITY'::text) THEN 'Liabilities'::character varying
            WHEN ((at.code)::text = 'EQUITY'::text) THEN 'Equity'::character varying
            ELSE at.code
        END AS category_name,
    a.account_code,
    a.account_name,
        CASE
            WHEN ((a.normal_balance)::text = 'DEBIT'::text) THEN (sum(jel.debit_amount) - sum(jel.credit_amount))
            ELSE (sum(jel.credit_amount) - sum(jel.debit_amount))
        END AS balance
   FROM (((accounting.journal_entry_lines jel
     JOIN accounting.journal_entries je ON ((je.journal_entry_id = jel.journal_entry_id)))
     JOIN accounting.accounts a ON ((a.account_id = jel.account_id)))
     JOIN accounting.account_types at ON ((at.account_type_id = a.account_type_id)))
  WHERE (((je.status)::text = 'POSTED'::text) AND (at.is_balance_sheet = true))
  GROUP BY at.code, at.sort_order, a.account_id, a.account_code, a.account_name, a.normal_balance
  ORDER BY at.sort_order, a.account_code;


ALTER VIEW accounting.view_balance_sheet OWNER TO postgres;

--
-- TOC entry 769 (class 1259 OID 118422)
-- Name: view_general_ledger; Type: VIEW; Schema: accounting; Owner: postgres
--

CREATE VIEW accounting.view_general_ledger AS
 SELECT a.account_code,
    a.account_name,
    je.entry_date,
    je.entry_number,
    je.description,
    jel.description AS line_description,
    jel.debit_amount,
    jel.credit_amount,
    sum(
        CASE
            WHEN ((a.normal_balance)::text = 'DEBIT'::text) THEN (jel.debit_amount - jel.credit_amount)
            ELSE (jel.credit_amount - jel.debit_amount)
        END) OVER (PARTITION BY a.account_id ORDER BY je.entry_date, je.created_at ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance
   FROM ((accounting.journal_entry_lines jel
     JOIN accounting.journal_entries je ON ((je.journal_entry_id = jel.journal_entry_id)))
     JOIN accounting.accounts a ON ((a.account_id = jel.account_id)))
  WHERE ((je.status)::text = 'POSTED'::text)
  ORDER BY a.account_code, je.entry_date, je.created_at;


ALTER VIEW accounting.view_general_ledger OWNER TO postgres;

--
-- TOC entry 770 (class 1259 OID 118427)
-- Name: view_profit_and_loss; Type: VIEW; Schema: accounting; Owner: postgres
--

CREATE VIEW accounting.view_profit_and_loss AS
 SELECT at.code AS category,
        CASE
            WHEN ((at.code)::text = 'REVENUE'::text) THEN 'Revenue'::character varying
            WHEN ((at.code)::text = 'COGS'::text) THEN 'Cost of Goods Sold'::character varying
            WHEN ((at.code)::text = 'EXPENSE'::text) THEN 'Operating Expenses'::character varying
            WHEN ((at.code)::text = 'OTHER_INCOME'::text) THEN 'Other Income'::character varying
            WHEN ((at.code)::text = 'OTHER_EXPENSE'::text) THEN 'Other Expenses'::character varying
            ELSE at.code
        END AS category_name,
    a.account_code,
    a.account_name,
    (sum(jel.credit_amount) - sum(jel.debit_amount)) AS net_amount
   FROM (((accounting.journal_entry_lines jel
     JOIN accounting.journal_entries je ON ((je.journal_entry_id = jel.journal_entry_id)))
     JOIN accounting.accounts a ON ((a.account_id = jel.account_id)))
     JOIN accounting.account_types at ON ((at.account_type_id = a.account_type_id)))
  WHERE (((je.status)::text = 'POSTED'::text) AND (at.is_profit_and_loss = true))
  GROUP BY at.code, at.sort_order, a.account_id, a.account_code, a.account_name
  ORDER BY at.sort_order, a.account_code;


ALTER VIEW accounting.view_profit_and_loss OWNER TO postgres;

--
-- TOC entry 768 (class 1259 OID 118417)
-- Name: view_trial_balance; Type: VIEW; Schema: accounting; Owner: postgres
--

CREATE VIEW accounting.view_trial_balance AS
 SELECT a.account_code,
    a.account_name,
    at.code AS account_type,
    a.normal_balance,
    sum(jel.debit_amount) AS total_debit,
    sum(jel.credit_amount) AS total_credit,
        CASE
            WHEN ((a.normal_balance)::text = 'DEBIT'::text) THEN (sum(jel.debit_amount) - sum(jel.credit_amount))
            ELSE (sum(jel.credit_amount) - sum(jel.debit_amount))
        END AS balance
   FROM (((accounting.journal_entry_lines jel
     JOIN accounting.journal_entries je ON ((je.journal_entry_id = jel.journal_entry_id)))
     JOIN accounting.accounts a ON ((a.account_id = jel.account_id)))
     JOIN accounting.account_types at ON ((at.account_type_id = a.account_type_id)))
  WHERE ((je.status)::text = 'POSTED'::text)
  GROUP BY a.account_id, a.account_code, a.account_name, at.code, a.normal_balance
  ORDER BY a.account_code;


ALTER VIEW accounting.view_trial_balance OWNER TO postgres;

