--
-- TOC entry 496 (class 1259 OID 108942)
-- Name: catalog_product_360; Type: VIEW; Schema: catalog; Owner: postgres
--

CREATE VIEW catalog.catalog_product_360 AS
 SELECT p.product_id,
    p.company_id,
    p.catalog_id,
    p.product_code,
    p.product_name,
    p.slug,
    p.short_description,
    p.description,
    prt.code AS product_type_code,
    prt.name AS product_type_name,
    b.brand_id,
    b.brand_code,
    b.brand_name,
    ps.code AS status_code,
    ps.name AS status_name,
    u.code AS default_uom_code,
    p.is_active,
    p.is_visible,
    p.is_featured,
    p.published_at,
    p.created_at,
    p.updated_at,
    pc.category_id AS primary_category_id,
    pc.category_name AS primary_category_name,
    dv.variant_id AS default_variant_id,
    dv.variant_code AS default_variant_code,
    dv.variant_name AS default_variant_name,
    dsku.sku_id AS default_sku_id,
    dsku.sku_code AS default_sku_code,
    COALESCE(vars.variant_count, (0)::bigint) AS variant_count,
    COALESCE(med.media_count, (0)::bigint) AS media_count,
    COALESCE(docs.document_count, (0)::bigint) AS document_count,
    COALESCE(cats.categories_json, '[]'::jsonb) AS categories,
    COALESCE(vars.variants_json, '[]'::jsonb) AS variants,
    COALESCE(tags.tags_json, '[]'::jsonb) AS tags,
    COALESCE(colls.collections_json, '[]'::jsonb) AS collections,
    COALESCE(specs.specifications_json, '{}'::jsonb) AS specifications,
    COALESCE(avail.availability_json, '[]'::jsonb) AS availability_channels,
    COALESCE(phys.physical_infos_json, '[]'::jsonb) AS physical_infos
   FROM ((((((((((((((((catalog.products p
     JOIN catalog.product_type_lookup prt ON ((prt.product_type_id = p.product_type_id)))
     LEFT JOIN catalog.brands b ON (((b.brand_id = p.brand_id) AND (b.company_id = p.company_id))))
     LEFT JOIN catalog.product_status_lookup ps ON ((ps.product_status_id = p.product_status_id)))
     LEFT JOIN catalog.uom_lookup u ON ((u.uom_id = p.default_uom_id)))
     LEFT JOIN LATERAL ( SELECT c.category_id,
            c.category_name
           FROM (catalog.product_categories pcat
             JOIN catalog.categories c ON ((c.category_id = pcat.category_id)))
          WHERE (pcat.product_id = p.product_id)
          ORDER BY pcat.is_primary DESC, pcat.sort_order
         LIMIT 1) pc ON (true))
     LEFT JOIN LATERAL ( SELECT v.variant_id,
            v.variant_code,
            v.variant_name
           FROM catalog.product_variants v
          WHERE ((v.product_id = p.product_id) AND (v.is_default = true))
         LIMIT 1) dv ON (true))
     LEFT JOIN LATERAL ( SELECT s.sku_id,
            s.sku_code
           FROM catalog.product_skus s
          WHERE ((s.variant_id = dv.variant_id) AND (s.is_active = true))
          ORDER BY s.is_primary DESC, s.created_at
         LIMIT 1) dsku ON (true))
     LEFT JOIN LATERAL ( SELECT count(v.variant_id) AS variant_count,
            COALESCE(jsonb_agg(jsonb_build_object('variant_id', v.variant_id, 'variant_code', v.variant_code, 'variant_name', v.variant_name, 'is_default', v.is_default, 'is_active', v.is_active, 'sku_code', s.sku_code) ORDER BY v.sort_order), '[]'::jsonb) AS variants_json
           FROM (catalog.product_variants v
             LEFT JOIN catalog.product_skus s ON (((s.variant_id = v.variant_id) AND (s.is_primary = true))))
          WHERE (v.product_id = p.product_id)) vars ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS media_count
           FROM catalog.product_media m
          WHERE ((m.product_id = p.product_id) AND (m.is_active = true))) med ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS document_count
           FROM catalog.product_documents d
          WHERE ((d.product_id = p.product_id) AND (d.is_active = true))) docs ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(jsonb_agg(jsonb_build_object('category_id', c.category_id, 'category_name', c.category_name, 'is_primary', pcat.is_primary, 'sort_order', pcat.sort_order) ORDER BY pcat.is_primary DESC, pcat.sort_order), '[]'::jsonb) AS categories_json
           FROM (catalog.product_categories pcat
             JOIN catalog.categories c ON ((c.category_id = pcat.category_id)))
          WHERE (pcat.product_id = p.product_id)) cats ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(jsonb_agg(jsonb_build_object('tag_code', t.tag_code, 'tag_name', t.tag_name) ORDER BY t.sort_order), '[]'::jsonb) AS tags_json
           FROM (catalog.product_tags pt
             JOIN catalog.tags t ON (((t.tag_id = pt.tag_id) AND (t.company_id = pt.company_id))))
          WHERE ((pt.product_id = p.product_id) AND (pt.is_active = true))) tags ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(jsonb_agg(jsonb_build_object('collection_code', c.collection_code, 'collection_name', c.collection_name, 'sort_order', cp.sort_order) ORDER BY cp.sort_order), '[]'::jsonb) AS collections_json
           FROM (catalog.collection_products cp
             JOIN catalog.collections c ON ((c.collection_id = cp.collection_id)))
          WHERE (cp.product_id = p.product_id)) colls ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(jsonb_object_agg(sd.spec_code, COALESCE(sp.value_text, (sp.value_number)::text, (sp.value_boolean)::text, (sp.value_date)::text)), '{}'::jsonb) AS specifications_json
           FROM (catalog.product_specifications sp
             JOIN catalog.spec_definitions sd ON ((sd.spec_definition_id = sp.spec_definition_id)))
          WHERE ((sp.product_id = p.product_id) AND (sp.is_active = true))) specs ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(jsonb_agg(jsonb_build_object('channel_code', ac.code, 'channel_name', ac.name, 'is_enabled', pa.is_enabled) ORDER BY ac.sort_order), '[]'::jsonb) AS availability_json
           FROM (catalog.product_availability pa
             JOIN catalog.availability_channel_lookup ac ON ((ac.availability_channel_id = pa.availability_channel_id)))
          WHERE (pa.product_id = p.product_id)) avail ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(jsonb_agg(jsonb_build_object('context_code', phi.context_code, 'weight', phi.weight, 'length', phi.length, 'width', phi.width, 'height', phi.height, 'volume', phi.volume) ORDER BY phi.context_code), '[]'::jsonb) AS physical_infos_json
           FROM catalog.product_physical_infos phi
          WHERE ((phi.product_id = p.product_id) AND (phi.is_active = true))) phys ON (true));


ALTER VIEW catalog.catalog_product_360 OWNER TO postgres;

