-- Name: read_product_tags; Type: VIEW; Schema: catalog; Owner: postgres
--

CREATE VIEW catalog.read_product_tags AS
 SELECT p.product_id,
    p.company_id,
    p.product_code,
    t.tag_id,
    t.tag_code,
    t.tag_name,
    pt.sort_order
   FROM ((catalog.product_tags pt
     JOIN catalog.products p ON ((p.product_id = pt.product_id)))
     JOIN catalog.tags t ON (((t.tag_id = pt.tag_id) AND (t.company_id = pt.company_id))));


ALTER VIEW catalog.read_product_tags OWNER TO postgres;

--
-- TOC entry 489 (class 1259 OID 108907)
-- Name: read_product_variant_skus; Type: VIEW; Schema: catalog; Owner: postgres
--

CREATE VIEW catalog.read_product_variant_skus AS
 SELECT p.product_id,
    p.company_id,
    p.product_code,
    v.variant_id,
    v.variant_code,
    v.variant_name,
    v.is_default,
    v.is_active AS variant_is_active,
    v.sort_order AS variant_sort_order,
    s.sku_id,
    s.sku_code,
    s.is_primary AS sku_is_primary,
    s.is_active AS sku_is_active
   FROM ((catalog.products p
     JOIN catalog.product_variants v ON ((v.product_id = p.product_id)))
     LEFT JOIN catalog.product_skus s ON ((s.variant_id = v.variant_id)));


