--
-- TOC entry 378 (class 1259 OID 106536)
-- Name: vw_customer_360_documents; Type: VIEW; Schema: crm; Owner: postgres
--

CREATE VIEW crm.vw_customer_360_documents AS
 SELECT c.company_id,
    c.customer_id,
    c.customer_number,
    c.display_name,
    d.customer_document_id,
    d.document_type_id,
    dt.code AS document_type,
    dt.name AS document_type_name,
    d.document_verification_status_id,
    dvs.code AS verification_status,
    dvs.name AS verification_status_name,
    d.document_number,
    d.document_title,
    d.issuing_authority,
    d.issue_date,
    d.expiry_date,
        CASE
            WHEN (d.expiry_date IS NULL) THEN false
            WHEN (d.expiry_date < CURRENT_DATE) THEN true
            ELSE false
        END AS is_expired,
        CASE
            WHEN (d.expiry_date IS NULL) THEN NULL::integer
            WHEN (d.expiry_date < CURRENT_DATE) THEN 0
            ELSE (d.expiry_date - CURRENT_DATE)
        END AS days_until_expiry,
    d.storage_provider,
    d.storage_bucket,
    d.storage_key,
    d.storage_url,
    d.original_file_name,
    d.file_extension,
    d.mime_type,
    d.file_size_bytes,
    d.file_hash,
    d.verification_notes,
    d.is_verified,
    d.is_current,
    d.is_active,
    d.created_at,
    d.created_by_user_id,
    d.updated_at,
    d.updated_by_user_id
   FROM (((crm.customer_documents d
     JOIN crm.customers c ON (((c.company_id = d.company_id) AND (c.customer_id = d.customer_id))))
     JOIN reference.document_type_lookup dt ON ((dt.document_type_id = d.document_type_id)))
     JOIN crm.document_verification_status_lookup dvs ON ((dvs.document_verification_status_id = d.document_verification_status_id)));


ALTER VIEW crm.vw_customer_360_documents OWNER TO postgres;

