--
-- TOC entry 380 (class 1259 OID 106546)
-- Name: vw_customer_360_document_compliance; Type: VIEW; Schema: crm; Owner: postgres
--

CREATE VIEW crm.vw_customer_360_document_compliance AS
 SELECT c.company_id,
    c.customer_id,
    c.customer_number,
    c.display_name,
    count(d.customer_document_id) AS total_documents,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true))) AS current_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.is_verified = true))) AS verified_current_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.is_verified = false))) AS unverified_current_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND ((dvs.code)::text = 'VERIFIED'::text))) AS verified_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND ((dvs.code)::text = 'PENDING'::text))) AS pending_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND ((dvs.code)::text = 'REJECTED'::text))) AS rejected_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND ((dvs.code)::text = 'EXPIRED'::text))) AS expired_status_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.expiry_date IS NOT NULL) AND (d.expiry_date < CURRENT_DATE))) AS expired_document_count,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.expiry_date IS NOT NULL) AND (d.expiry_date >= CURRENT_DATE) AND (d.expiry_date <= (CURRENT_DATE + 30)))) AS documents_expiring_within_30_days,
    count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.expiry_date IS NOT NULL) AND (d.expiry_date > (CURRENT_DATE + 30)))) AS documents_valid_beyond_30_days,
    max(d.created_at) AS latest_document_uploaded_at,
    max(d.updated_at) AS latest_document_updated_at,
    min(d.expiry_date) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.expiry_date IS NOT NULL) AND (d.expiry_date >= CURRENT_DATE))) AS nearest_document_expiry_date,
        CASE
            WHEN (count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true))) = 0) THEN 'NO_CURRENT_DOCUMENTS'::text
            WHEN (count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND (d.is_verified = false))) > 0) THEN 'DOCUMENTS_REQUIRE_VERIFICATION'::text
            WHEN (count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND ((d.expiry_date IS NOT NULL) AND (d.expiry_date < CURRENT_DATE)))) > 0) THEN 'DOCUMENTS_EXPIRED'::text
            WHEN (count(d.customer_document_id) FILTER (WHERE ((d.is_current = true) AND (d.is_active = true) AND ((dvs.code)::text = 'REJECTED'::text))) > 0) THEN 'DOCUMENTS_REJECTED'::text
            ELSE 'DOCUMENTS_COMPLIANT'::text
        END AS document_compliance_status
   FROM ((crm.customers c
     LEFT JOIN crm.customer_documents d ON (((d.company_id = c.company_id) AND (d.customer_id = c.customer_id))))
     LEFT JOIN crm.document_verification_status_lookup dvs ON ((dvs.document_verification_status_id = d.document_verification_status_id)))
  GROUP BY c.company_id, c.customer_id, c.customer_number, c.display_name;


ALTER VIEW crm.vw_customer_360_document_compliance OWNER TO postgres;

--
