--
-- TOC entry 374 (class 1259 OID 106461)
-- Name: vw_customer_360_privacy_summary; Type: VIEW; Schema: crm; Owner: postgres
--

CREATE VIEW crm.vw_customer_360_privacy_summary AS
 WITH latest_consents AS (
         SELECT cc_1.customer_consent_id,
            cc_1.company_id,
            cc_1.customer_id,
            cc_1.customer_consent_type_id,
            cc_1.customer_consent_source_id,
            cc_1.is_granted,
            cc_1.consented_at,
            cc_1.withdrawn_at,
            cc_1.source_reference,
            cc_1.evidence_reference,
            cc_1.ip_address,
            cc_1.user_agent,
            cc_1.notes,
            cc_1.created_at,
            cc_1.created_by_user_id,
            row_number() OVER (PARTITION BY cc_1.company_id, cc_1.customer_id, cc_1.customer_consent_type_id ORDER BY cc_1.consented_at DESC, cc_1.customer_consent_id DESC) AS rn
           FROM crm.customer_consents cc_1
        ), current_consents AS (
         SELECT latest_consents.customer_consent_id,
            latest_consents.company_id,
            latest_consents.customer_id,
            latest_consents.customer_consent_type_id,
            latest_consents.customer_consent_source_id,
            latest_consents.is_granted,
            latest_consents.consented_at,
            latest_consents.withdrawn_at,
            latest_consents.source_reference,
            latest_consents.evidence_reference,
            latest_consents.ip_address,
            latest_consents.user_agent,
            latest_consents.notes,
            latest_consents.created_at,
            latest_consents.created_by_user_id,
            latest_consents.rn
           FROM latest_consents
          WHERE (latest_consents.rn = 1)
        )
 SELECT c.company_id,
    c.customer_id,
    c.customer_number,
    c.display_name,
    c.accepts_marketing,
    c.accepts_email,
    c.accepts_sms,
    c.accepts_phone,
    cp.preferred_contact_method_id,
    pcm.code AS preferred_contact_method,
    cp.prefers_digital_communication,
    count(cc.customer_consent_id) AS total_consent_records,
    count(*) FILTER (WHERE (cc.is_granted = true)) AS granted_consent_count,
    count(*) FILTER (WHERE (cc.is_granted = false)) AS withdrawn_consent_count,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'MARKETING'::text))) AS has_marketing_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'EMAIL_MARKETING'::text))) AS has_email_marketing_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'SMS_MARKETING'::text))) AS has_sms_marketing_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'PHONE_MARKETING'::text))) AS has_phone_marketing_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'WHATSAPP_MARKETING'::text))) AS has_whatsapp_marketing_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'PERSONALIZATION'::text))) AS has_personalization_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'ANALYTICS'::text))) AS has_analytics_consent,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'THIRD_PARTY_SHARING'::text))) AS has_third_party_sharing_consent,
    max(cc.consented_at) AS last_consent_granted_at,
    max(cc.withdrawn_at) AS last_consent_withdrawn_at,
    max(GREATEST(cc.consented_at, COALESCE(cc.withdrawn_at, cc.consented_at))) AS last_consent_activity_at,
    ((c.accepts_marketing = true) AND bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'MARKETING'::text)))) AS marketing_allowed,
    ((c.accepts_email = true) AND bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'EMAIL_MARKETING'::text)))) AS email_marketing_allowed,
    ((c.accepts_sms = true) AND bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'SMS_MARKETING'::text)))) AS sms_marketing_allowed,
    ((c.accepts_phone = true) AND bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'PHONE_MARKETING'::text)))) AS phone_marketing_allowed,
    bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'WHATSAPP_MARKETING'::text))) AS whatsapp_marketing_allowed,
        CASE
            WHEN (count(cc.customer_consent_id) = 0) THEN 'NO_CONSENT_RECORDS'::text
            WHEN ((c.accepts_marketing = true) AND bool_or(((cc.is_granted = true) AND ((ct.code)::text = 'MARKETING'::text)))) THEN 'MARKETING_CONSENTED'::text
            WHEN bool_or((cc.is_granted = false)) THEN 'CONSENT_WITHDRAWN'::text
            ELSE 'PARTIAL_CONSENT'::text
        END AS consent_compliance_status
   FROM ((((crm.customers c
     LEFT JOIN crm.customer_preferences cp ON ((cp.customer_id = c.customer_id)))
     LEFT JOIN crm.customer_contact_method_lookup pcm ON ((pcm.customer_contact_method_id = cp.preferred_contact_method_id)))
     LEFT JOIN current_consents cc ON (((cc.company_id = c.company_id) AND (cc.customer_id = c.customer_id))))
     LEFT JOIN crm.customer_consent_type_lookup ct ON ((ct.customer_consent_type_id = cc.customer_consent_type_id)))
  GROUP BY c.company_id, c.customer_id, c.customer_number, c.display_name, c.accepts_marketing, c.accepts_email, c.accepts_sms, c.accepts_phone, cp.preferred_contact_method_id, pcm.code, cp.prefers_digital_communication;


ALTER VIEW crm.vw_customer_360_privacy_summary OWNER TO postgres;

