CREATE TABLE identity.persons (
    person_id uuid DEFAULT gen_random_uuid() NOT NULL,
    first_name character varying(100) NOT NULL,
    middle_name character varying(100),
    last_name character varying(100) NOT NULL,
    display_name character varying(250),
    date_of_birth date,
    gender_type_id uuid,
    email public.citext,
    mobile_phone character varying(30),
    alternate_phone character varying(30),
    national_id character varying(100),
    profile_image_url text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by_user_id uuid,
    updated_at timestamp with time zone,
    updated_by_user_id uuid,
    CONSTRAINT chk_person_first_name CHECK ((btrim((first_name)::text) <> ''::text)),
    CONSTRAINT chk_person_last_name CHECK ((btrim((last_name)::text) <> ''::text))
);


