    c.phone,
    c.mobile,
    c.website_url,
    c.registration_number,
    c.tax_number,
    c.credit_limit,
    c.payment_terms_days,
    c.is_vip,
    c.is_tax_exempt,
    c.is_active,
    c.accepts_marketing,
    c.accepts_sms,
    c.accepts_email,
    c.accepts_phone,
    cp.customer_credit_status_id,
    ccs.code AS credit_status,
    cp.customer_credit_risk_level_id,
    ccr.code AS credit_risk_level,
    cp.credit_limit AS commercial_credit_limit,
    cp.temporary_credit_limit,
    cp.temporary_credit_limit_from,
    cp.temporary_credit_limit_to,
    cp.payment_terms_days AS commercial_payment_terms_days,
    cp.minimum_order_amount,
