    cp.maximum_open_orders,
    cp.requires_purchase_order,
    cp.requires_credit_approval,
    cp.tax_invoice_required,
    cp.allow_partial_shipments,
    cp.allow_backorders,
    cp.allow_credit_orders,
    pref.preferred_language_id,
    lang.code AS preferred_language,
    pref.preferred_currency_id,
    cur.code AS preferred_currency,
    pref.preferred_contact_method_id,
    pcm.code AS preferred_contact_method,
    pref.preferred_contact_start_time,
    pref.preferred_contact_end_time,
    pref.preferred_contact_days,
    pref.accepts_phone AS preference_accepts_phone,
    pref.accepts_email AS preference_accepts_email,
    pref.accepts_sms AS preference_accepts_sms,
    pref.prefers_digital_communication,
    pref.preferred_delivery_instructions,
    s.first_interaction_at,
    s.last_interaction_at,
    s.total_interactions,
    s.total_service_cases,
    s.open_service_cases,
    s.resolved_service_cases,
    s.total_tasks,
    s.open_tasks,
    s.overdue_tasks,
    s.completed_tasks,
    s.referrals_given,
    s.referrals_received,
    s.successful_referrals_given,
    s.successful_referrals_received,
    s.total_orders,
    s.total_order_amount,
    s.average_order_amount,
    s.last_order_at,
    s.total_paid_amount,
    s.outstanding_amount,
    s.last_payment_at,
    s.lifetime_value,
    s.last_service_case_at,
    s.last_task_at,
    s.last_referral_at,
    s.data_quality_score,
    s.last_calculated_at AS summary_calculated_at,
    s.current_overall_score,
    s.current_risk_score,
    s.current_engagement_score,
    s.current_value_score,
    s.current_loyalty_score,
    s.current_fraud_score,
    c.created_at AS customer_created_at,
    c.updated_at AS customer_updated_at
   FROM (((((((((((crm.customers c
     JOIN crm.customer_type_lookup ct ON ((ct.customer_type_id = c.customer_type_id)))
     JOIN crm.customer_status_lookup cs ON ((cs.customer_status_id = c.customer_status_id)))
     LEFT JOIN identity.persons p ON ((p.person_id = c.person_id)))
     LEFT JOIN crm.customer_commercial_profiles cp ON (((cp.company_id = c.company_id) AND (cp.customer_id = c.customer_id))))
     LEFT JOIN crm.customer_credit_status_lookup ccs ON ((ccs.customer_credit_status_id = cp.customer_credit_status_id)))
     LEFT JOIN crm.customer_credit_risk_level_lookup ccr ON ((ccr.customer_credit_risk_level_id = cp.customer_credit_risk_level_id)))
     LEFT JOIN crm.customer_preferences pref ON ((pref.customer_id = c.customer_id)))
     LEFT JOIN reference.language_lookup lang ON ((lang.language_id = pref.preferred_language_id)))
     LEFT JOIN reference.currency_lookup cur ON ((cur.currency_id = pref.preferred_currency_id)))
     LEFT JOIN crm.customer_contact_method_lookup pcm ON ((pcm.customer_contact_method_id = pref.preferred_contact_method_id)))
     LEFT JOIN crm.customer_account_summary s ON (((s.company_id = c.company_id) AND (s.customer_id = c.customer_id))));


