CREATE VIEW crm.vw_customer_360_relationships AS
 SELECT r.company_id,
    r.source_customer_id AS customer_id,
    'OUTGOING'::character varying(20) AS relationship_direction,
    r.customer_relationship_id,
    r.target_customer_id AS related_customer_id,
    source_customer.customer_number,
    source_customer.display_name AS customer_name,
    target_customer.customer_number AS related_customer_number,
    target_customer.display_name AS related_customer_name,
    rt.code AS relationship_type,
    rt.name AS relationship_type_name,
    r.description,
    r.effective_from,
    r.effective_to,
    r.is_active,
    r.created_at,
    r.updated_at
   FROM (((crm.customer_relationships r
     JOIN crm.customers source_customer ON (((source_customer.company_id = r.company_id) AND (source_customer.customer_id = r.source_customer_id))))
     JOIN crm.customers target_customer ON (((target_customer.company_id = r.company_id) AND (target_customer.customer_id = r.target_customer_id))))
     JOIN crm.customer_relationship_type_lookup rt ON ((rt.customer_relationship_type_id = r.customer_relationship_type_id)))
  WHERE (r.is_active = true)
UNION ALL
 SELECT r.company_id,
    r.target_customer_id AS customer_id,
    'INCOMING'::character varying(20) AS relationship_direction,
    r.customer_relationship_id,
    r.source_customer_id AS related_customer_id,
    target_customer.customer_number,
    target_customer.display_name AS customer_name,
    source_customer.customer_number AS related_customer_number,
    source_customer.display_name AS related_customer_name,
    rt.code AS relationship_type,
    rt.name AS relationship_type_name,
    r.description,
    r.effective_from,
    r.effective_to,
    r.is_active,
    r.created_at,
    r.updated_at
   FROM (((crm.customer_relationships r
     JOIN crm.customers source_customer ON (((source_customer.company_id = r.company_id) AND (source_customer.customer_id = r.source_customer_id))))
     JOIN crm.customers target_customer ON (((target_customer.company_id = r.company_id) AND (target_customer.customer_id = r.target_customer_id))))
     JOIN crm.customer_relationship_type_lookup rt ON ((rt.customer_relationship_type_id = r.customer_relationship_type_id)))
  WHERE (r.is_active = true);


