 SELECT cd.company_id,
    cd.customer_id,
    cd.customer_document_id AS document_id,
    dt.code AS document_type,
    COALESCE(cd.document_title, cd.original_file_name) AS document_title,
    cd.document_number,
    cd.issuing_authority,
    cd.issue_date,
    cd.expiry_date,
    dvs.code AS verification_status,
    cd.is_verified,
    cd.is_current,
    cd.is_active,
    cd.storage_provider,
    cd.storage_bucket,
    cd.storage_key,
    cd.storage_url,
    cd.original_file_name,
    cd.file_extension,
    cd.mime_type,
    cd.file_size_bytes,
    cd.file_hash,
    cd.verification_notes,
    cd.created_at,
    cd.created_by_user_id,
    cd.updated_at,
    cd.updated_by_user_id
   FROM ((crm.customer_documents cd
     JOIN reference.document_type_lookup dt ON ((dt.document_type_id = cd.document_type_id)))
     JOIN crm.document_verification_status_lookup dvs ON ((dvs.document_verification_status_id = cd.document_verification_status_id)));


