--
-- TOC entry 363 (class 1259 OID 106354)
-- Name: vw_customer_activity_timeline; Type: VIEW; Schema: crm; Owner: postgres
--

CREATE VIEW crm.vw_customer_activity_timeline AS
 SELECT ci.customer_id,
    c.company_id,
    ci.customer_interaction_id AS activity_id,
    'INTERACTION'::character varying(50) AS activity_category,
    (COALESCE(it.code, 'OTHER'::character varying))::character varying(100) AS activity_type,
    (COALESCE(is1.code, 'UNKNOWN'::character varying))::character varying(100) AS activity_status,
    (COALESCE(idr.code, 'UNKNOWN'::character varying))::character varying(100) AS activity_direction,
    ci.subject AS title,
    ci.interaction_notes AS description,
    ci.created_at AS activity_at,
    ci.user_id AS performed_by_user_id,
    ci.employee_id AS performed_by_employee_id,
    ci.person_id AS related_person_id,
    ci.customer_contact_id AS related_contact_id,
    ci.customer_service_case_id AS related_case_id,
    NULL::uuid AS related_task_id,
    NULL::uuid AS related_document_id,
    NULL::jsonb AS activity_data
   FROM ((((crm.customer_interactions ci
     JOIN crm.customers c ON ((c.customer_id = ci.customer_id)))
     LEFT JOIN crm.customer_interaction_type_lookup it ON ((it.customer_interaction_type_id = ci.customer_interaction_type_id)))
     LEFT JOIN crm.customer_interaction_status_lookup is1 ON ((is1.customer_interaction_status_id = ci.customer_interaction_status_id)))
     LEFT JOIN crm.customer_interaction_direction_lookup idr ON ((idr.customer_interaction_direction_id = ci.customer_interaction_direction_id)))
UNION ALL
 SELECT sc.customer_id,
    sc.company_id,
    sc.customer_service_case_id AS activity_id,
    'SERVICE_CASE'::character varying(50) AS activity_category,
    (COALESCE(sct.code, 'OTHER'::character varying))::character varying(100) AS activity_type,
    (COALESCE(scs.code, 'UNKNOWN'::character varying))::character varying(100) AS activity_status,
    (COALESCE(scp.code, 'UNKNOWN'::character varying))::character varying(100) AS activity_direction,
    sc.subject AS title,
    sc.description,
    sc.created_at AS activity_at,
    sc.created_by_user_id AS performed_by_user_id,
    sc.assigned_employee_id AS performed_by_employee_id,
    NULL::uuid AS related_person_id,
    NULL::uuid AS related_contact_id,
    sc.customer_service_case_id AS related_case_id,
    NULL::uuid AS related_task_id,
    NULL::uuid AS related_document_id,
    jsonb_build_object('case_number', sc.case_number, 'priority', scp.code, 'source', scsrc.code, 'is_escalated', sc.is_escalated, 'escalation_level', sc.escalation_level) AS activity_data
   FROM ((((crm.customer_service_cases sc
     LEFT JOIN crm.customer_service_case_type_lookup sct ON ((sct.customer_service_case_type_id = sc.customer_service_case_type_id)))
     LEFT JOIN crm.customer_service_case_status_lookup scs ON ((scs.customer_service_case_status_id = sc.customer_service_case_status_id)))
     LEFT JOIN crm.customer_service_case_priority_lookup scp ON ((scp.customer_service_case_priority_id = sc.customer_service_case_priority_id)))
     LEFT JOIN crm.customer_service_case_source_lookup scsrc ON ((scsrc.customer_service_case_source_id = sc.customer_service_case_source_id)))
UNION ALL
 SELECT csc.customer_id,
    csc.company_id,
    cc.customer_service_case_comment_id AS activity_id,
    'CASE_COMMENT'::character varying(50) AS activity_category,
    (COALESCE(cct.code, 'OTHER'::character varying))::character varying(100) AS activity_type,
    (
        CASE
            WHEN cc.is_deleted THEN 'DELETED'::text
            WHEN cc.is_customer_visible THEN 'CUSTOMER_VISIBLE'::text
            ELSE 'INTERNAL'::text
        END)::character varying(100) AS activity_status,
    NULL::character varying(100) AS activity_direction,
    'Case Comment'::character varying AS title,
    cc.comment_text AS description,
    cc.created_at AS activity_at,
    cc.created_by_user_id AS performed_by_user_id,
    cc.employee_id AS performed_by_employee_id,
    cc.person_id AS related_person_id,
    NULL::uuid AS related_contact_id,
    cc.customer_service_case_id AS related_case_id,
    NULL::uuid AS related_task_id,
    NULL::uuid AS related_document_id,
    jsonb_build_object('comment_type', cct.code, 'customer_visible', cc.is_customer_visible, 'deleted', cc.is_deleted, 'interaction_id', cc.customer_interaction_id, 'reply_to_comment_id', cc.reply_to_comment_id) AS activity_data
   FROM ((crm.customer_service_case_comments cc
     JOIN crm.customer_service_cases csc ON ((csc.customer_service_case_id = cc.customer_service_case_id)))
     LEFT JOIN crm.customer_service_case_comment_type_lookup cct ON ((cct.customer_service_case_comment_type_id = cc.customer_service_case_comment_type_id)))
UNION ALL
 SELECT ct.customer_id,
    ct.company_id,
    ct.customer_task_id AS activity_id,
    'TASK'::character varying(50) AS activity_category,
    (COALESCE(ctt.code, 'OTHER'::character varying))::character varying(100) AS activity_type,
    (COALESCE(cts.code, 'UNKNOWN'::character varying))::character varying(100) AS activity_status,
    (COALESCE(ctp.code, 'UNKNOWN'::character varying))::character varying(100) AS activity_direction,
    ct.title,
    ct.description,
    ct.created_at AS activity_at,
    ct.created_by_user_id AS performed_by_user_id,
    ct.assigned_employee_id AS performed_by_employee_id,
    NULL::uuid AS related_person_id,
