--
-- TOC entry 556 (class 1259 OID 110727)
-- Name: read_available_to_sell; Type: VIEW; Schema: inventory; Owner: postgres
--

CREATE VIEW inventory.read_available_to_sell AS
 SELECT i.company_id,
    p.product_id,
    p.product_code,
    p.product_name,
    v.variant_id,
    v.variant_code,
    v.variant_name,
    w.warehouse_id,
    w.warehouse_code,
    w.warehouse_name,
    sum(i.quantity_on_hand) AS on_hand,
    sum(i.quantity_reserved) AS reserved,
    sum(i.safety_stock) AS safety_stock,
    GREATEST((0)::numeric, ((sum(i.quantity_on_hand) - sum(i.quantity_reserved)) - sum(i.safety_stock))) AS available_to_sell
   FROM (((((inventory.inventories i
     JOIN catalog.products p ON ((p.product_id = i.product_id)))
     JOIN catalog.product_variants v ON ((v.variant_id = i.variant_id)))
     JOIN inventory.warehouses w ON ((w.warehouse_id = i.warehouse_id)))
     JOIN inventory.warehouse_locations l ON ((l.location_id = i.location_id)))
     JOIN inventory.location_type_lookup lt ON ((lt.location_type_id = l.location_type_id)))
  WHERE ((w.is_active = true) AND (l.is_active = true) AND (lt.is_sellable = true))
  GROUP BY i.company_id, p.product_id, p.product_code, p.product_name, v.variant_id, v.variant_code, v.variant_name, w.warehouse_id, w.warehouse_code, w.warehouse_name;


