--
-- TOC entry 560 (class 1259 OID 110746)
-- Name: read_inventory_valuation; Type: VIEW; Schema: inventory; Owner: postgres
--

CREATE VIEW inventory.read_inventory_valuation AS
 SELECT i.company_id,
    p.product_code,
    p.product_name,
    v.variant_code,
    v.variant_name,
    w.warehouse_code,
    w.warehouse_name,
    sum(i.quantity_on_hand) AS total_on_hand,
    sum((cl.quantity_remaining * cl.unit_cost)) AS total_cost_value,
        CASE
            WHEN (sum(i.quantity_on_hand) > (0)::numeric) THEN (sum((cl.quantity_remaining * cl.unit_cost)) / sum(i.quantity_on_hand))
            ELSE (0)::numeric
        END AS weighted_average_cost
   FROM ((((inventory.inventories i
     JOIN catalog.products p ON ((p.product_id = i.product_id)))
     JOIN catalog.product_variants v ON ((v.variant_id = i.variant_id)))
     JOIN inventory.warehouses w ON ((w.warehouse_id = i.warehouse_id)))
     LEFT JOIN inventory.inventory_cost_layers cl ON (((cl.variant_id = i.variant_id) AND (cl.warehouse_id = i.warehouse_id) AND (cl.quantity_remaining > (0)::numeric))))
  WHERE (i.quantity_on_hand > (0)::numeric)
  GROUP BY i.company_id, p.product_code, p.product_name, v.variant_code, v.variant_name, w.warehouse_code, w.warehouse_name;


