--
-- TOC entry 724 (class 1259 OID 117087)
-- Name: view_cash_variances; Type: VIEW; Schema: pos; Owner: postgres
--

CREATE VIEW pos.view_cash_variances AS
 SELECT shift_number,
    opened_by_user_id AS cashier_user_id,
    opening_amount,
    expected_cash_amount,
    actual_cash_amount,
    cash_difference,
        CASE
            WHEN (cash_difference IS NULL) THEN 'PENDING'::text
            WHEN (cash_difference = (0)::numeric) THEN 'BALANCED'::text
            WHEN (cash_difference > (0)::numeric) THEN 'OVERAGE'::text
            ELSE 'SHORTAGE'::text
        END AS variance_status,
    abs(COALESCE(cash_difference, (0)::numeric)) AS variance_amount,
    status AS shift_status,
    closed_at
   FROM pos.pos_shifts ps
  WHERE ((status)::text = ANY ((ARRAY['CLOSED'::character varying, 'DISPUTED'::character varying])::text[]))
  ORDER BY closed_at DESC;


ALTER VIEW pos.view_cash_variances OWNER TO postgres;

--
-- TOC entry 722 (class 1259 OID 117077)
-- Name: view_cashier_sales; Type: VIEW; Schema: pos; Owner: postgres
--

CREATE VIEW pos.view_cashier_sales AS
 SELECT ps.shift_number,
    ps.opened_by_user_id AS cashier_user_id,
    count(DISTINCT pct.pos_cash_transaction_id) AS total_transactions,
    sum(
        CASE
            WHEN ((pct.transaction_type)::text = 'SALE'::text) THEN pct.amount
            ELSE (0)::numeric
        END) AS total_sales,
    sum(
        CASE
            WHEN ((pct.transaction_type)::text = 'REFUND'::text) THEN abs(pct.amount)
            ELSE (0)::numeric
        END) AS total_refunds,
    sum(
        CASE
            WHEN ((pct.transaction_type)::text = ANY ((ARRAY['CASH_IN'::character varying, 'CASH_OUT'::character varying, 'PETTY_CASH'::character varying])::text[])) THEN pct.amount
            ELSE (0)::numeric
        END) AS total_cash_movements,
    ps.opening_amount,
    ps.expected_cash_amount,
    ps.actual_cash_amount,
    ps.cash_difference,
    ps.opened_at,
    ps.closed_at,
    (EXTRACT(epoch FROM (ps.closed_at - ps.opened_at)) / 3600.0) AS shift_duration_hours
   FROM (pos.pos_shifts ps
     JOIN pos.pos_cash_transactions pct ON ((pct.pos_shift_id = ps.pos_shift_id)))
  GROUP BY ps.pos_shift_id, ps.shift_number, ps.opened_by_user_id, ps.opening_amount, ps.expected_cash_amount, ps.actual_cash_amount, ps.cash_difference, ps.opened_at, ps.closed_at;


ALTER VIEW pos.view_cashier_sales OWNER TO postgres;

--
-- TOC entry 728 (class 1259 OID 117107)
