CREATE VIEW pos.view_offline_sync_status AS
 SELECT pt.terminal_code,
    pt.terminal_name,
    posq.operation_type,
    posq.status,
    posq.retry_count,
    posq.error_message,
    posq.created_at,
    posq.synced_at
   FROM (pos.pos_offline_sync_queue posq
     JOIN pos.pos_terminals pt ON ((pt.pos_terminal_id = posq.pos_terminal_id)))
  ORDER BY posq.created_at DESC;


ALTER VIEW pos.view_offline_sync_status OWNER TO postgres;

--
-- TOC entry 723 (class 1259 OID 117082)
-- Name: view_shift_transaction_metrics; Type: VIEW; Schema: pos; Owner: postgres
--

CREATE VIEW pos.view_shift_transaction_metrics AS
 SELECT ps.shift_number,
    ps.opened_by_user_id AS cashier_user_id,
    count(*) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)) AS sale_count,
    sum(pct.amount) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)) AS sale_total,
        CASE
            WHEN (count(*) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)) > 0) THEN (sum(pct.amount) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)) / (count(*) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)))::numeric)
            ELSE (0)::numeric
        END AS avg_transaction_value,
        CASE
            WHEN (EXTRACT(epoch FROM (ps.closed_at - ps.opened_at)) > (0)::numeric) THEN ((count(*) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)))::numeric / (EXTRACT(epoch FROM (ps.closed_at - ps.opened_at)) / 3600.0))
            ELSE (0)::numeric
        END AS transactions_per_hour
   FROM (pos.pos_shifts ps
     JOIN pos.pos_cash_transactions pct ON ((pct.pos_shift_id = ps.pos_shift_id)))
  GROUP BY ps.pos_shift_id, ps.shift_number, ps.opened_by_user_id, ps.opened_at, ps.closed_at;


ALTER VIEW pos.view_shift_transaction_metrics OWNER TO postgres;

--
-- TOC entry 725 (class 1259 OID 117092)
-- Name: view_store_inventory; Type: VIEW; Schema: pos; Owner: postgres
--

CREATE VIEW pos.view_store_inventory AS
 SELECT w.warehouse_code AS store_code,
    w.warehouse_name AS store_name,
    wl.location_code,
    wl.location_name,
    lt.code AS location_type,
    p.product_code,
    p.product_name,
    v.variant_code,
    v.variant_name,
    i.quantity_on_hand,
    i.quantity_reserved,
    GREATEST((0)::numeric, (i.quantity_on_hand - i.quantity_reserved)) AS available_to_sell,
    i.safety_stock
   FROM (((((inventory.inventories i
     JOIN inventory.warehouses w ON ((w.warehouse_id = i.warehouse_id)))
     JOIN inventory.warehouse_locations wl ON ((wl.location_id = i.location_id)))
     JOIN inventory.location_type_lookup lt ON ((lt.location_type_id = wl.location_type_id)))
     JOIN catalog.products p ON ((p.product_id = i.product_id)))
     JOIN catalog.product_variants v ON ((v.variant_id = i.variant_id)))
  WHERE (((w.warehouse_type)::text = 'PHYSICAL_STORE'::text) AND (lt.is_sellable = true));


ALTER VIEW pos.view_store_inventory OWNER TO postgres;

--
-- TOC entry 726 (class 1259 OID 117097)
-- Name: view_store_transfers; Type: VIEW; Schema: pos; Owner: postgres
--

CREATE VIEW pos.view_store_transfers AS
 SELECT st.transfer_number,
    fw.warehouse_code AS from_store,
    fw.warehouse_name AS from_store_name,
    tw.warehouse_code AS to_warehouse,
    tw.warehouse_name AS to_warehouse_name,
    st.status_id,
    st.transfer_date,
    st.received_at,
    count(sti.stock_transfer_item_id) AS item_count,
    sum(sti.requested_quantity) AS total_requested,
    sum(sti.received_quantity) AS total_received
   FROM (((inventory.stock_transfers st
     JOIN inventory.warehouses fw ON ((fw.warehouse_id = st.from_warehouse_id)))
     JOIN inventory.warehouses tw ON ((tw.warehouse_id = st.to_warehouse_id)))
     JOIN inventory.stock_transfer_items sti ON ((sti.stock_transfer_id = st.stock_transfer_id)))
  WHERE (((fw.warehouse_type)::text = 'PHYSICAL_STORE'::text) OR ((tw.warehouse_type)::text = 'PHYSICAL_STORE'::text))
  GROUP BY st.stock_transfer_id, st.transfer_number, fw.warehouse_code, fw.warehouse_name, tw.warehouse_code, tw.warehouse_name, st.status_id, st.transfer_date, st.received_at;


ALTER VIEW pos.view_store_transfers OWNER TO postgres;

--
-- TOC entry 727 (class 1259 OID 117102)
-- Name: view_terminal_dashboard; Type: VIEW; Schema: pos; Owner: postgres
--

CREATE VIEW pos.view_terminal_dashboard AS
 SELECT pt.terminal_code,
    pt.terminal_name,
    pt.location_description,
    pt.status AS terminal_status,
    pdc.device_type,
    pdc.app_version,
    pdc.offline_mode_enabled,
    pdc.last_sync_at,
    pdc.receipt_printer_model,
    pdc.barcode_scanner_model,
    pdc.card_reader_model,
    pr.register_code,
    pr.current_balance AS register_balance,
    pr.status AS register_status,
    ps.shift_number AS current_shift,
    ps.status AS shift_status,
    ps.opened_at AS shift_opened_at
   FROM (((pos.pos_terminals pt
     LEFT JOIN pos.pos_device_configurations pdc ON ((pdc.pos_terminal_id = pt.pos_terminal_id)))
     LEFT JOIN pos.pos_registers pr ON ((pr.company_id = pt.company_id)))
     LEFT JOIN pos.pos_shifts ps ON (((ps.pos_terminal_id = pt.pos_terminal_id) AND ((ps.status)::text = 'OPEN'::text))))
  WHERE (pt.is_active = true);


