    c.company_id,
    c.campaign_code,
    c.campaign_name,
    c.description,
    dt.code AS campaign_type_code,
    dt.name AS campaign_type_name,
    c.status_code,
    c.start_date,
    c.end_date,
    c.priority,
    c.is_stackable,
    sc.channel_code AS sales_channel_code,
    bu.unit_code AS business_unit_code,
