     LEFT JOIN pricing.sales_channels sc ON (((sc.sales_channel_id = c.sales_channel_id) AND (sc.company_id = c.company_id))))
     LEFT JOIN pricing.business_units bu ON (((bu.business_unit_id = c.business_unit_id) AND (bu.company_id = c.company_id))));


