-- Name: read_goods_receipts; Type: VIEW; Schema: purchasing; Owner: postgres
--

CREATE VIEW purchasing.read_goods_receipts AS
 SELECT gr.receipt_number,
    s.supplier_code,
    s.supplier_name,
    po.purchase_order_number,
    w.warehouse_code,
    gr.receipt_date,
    gr.status
   FROM (((purchasing.goods_receipts gr
     JOIN purchasing.suppliers s ON ((s.supplier_id = gr.supplier_id)))
     LEFT JOIN purchasing.purchase_orders po ON ((po.purchase_order_id = gr.purchase_order_id)))
     JOIN inventory.warehouses w ON ((w.warehouse_id = gr.warehouse_id)));


