    lcd.status
   FROM (((purchasing.landed_cost_documents lcd
     LEFT JOIN purchasing.purchase_orders po ON ((po.purchase_order_id = lcd.purchase_order_id)))
     LEFT JOIN purchasing.goods_receipts gr ON ((gr.goods_receipt_id = lcd.goods_receipt_id)))
     JOIN reference.currency_lookup c ON ((c.currency_id = lcd.currency_id)));


