--
-- TOC entry 856 (class 1259 OID 156734)
-- Name: vw_account_rep_performance; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_account_rep_performance AS
 SELECT ar.employee_id,
    c.company_id,
    COALESCE(((p.first_name || ' '::text) || p.last_name), ''::text) AS rep_name,
    reports.fn_account_rep_role(ar.role) AS rep_role,
    count(DISTINCT ar.customer_id) AS assigned_customers,
    sum(COALESCE(cas.order_total, (0)::numeric)) AS total_revenue_managed,
    round(avg(COALESCE(cas.order_count, 0)), 2) AS avg_orders_per_customer,
    count(DISTINCT
        CASE
            WHEN (COALESCE(cas.last_interaction_at, cas.last_case_at) >= (CURRENT_TIMESTAMP - '30 days'::interval)) THEN ar.customer_id
            ELSE NULL::uuid
        END) AS active_customers_30days,
    (array_agg(c.name ORDER BY cas.order_total DESC NULLS LAST))[1] AS top_customer_name
   FROM ((((public.account_representatives ar
     LEFT JOIN public.customers c ON ((c.id = ar.customer_id)))
     LEFT JOIN public.employees e ON ((e.id = ar.employee_id)))
     LEFT JOIN public.persons p ON ((p.id = e.person_id)))
     LEFT JOIN public.customer_account_summaries cas ON ((cas.customer_id = ar.customer_id)))
  WHERE (ar.is_primary = true)
  GROUP BY ar.employee_id, c.company_id, p.first_name, p.last_name, ar.role
  ORDER BY (sum(COALESCE(cas.order_total, (0)::numeric))) DESC;


ALTER VIEW reports.vw_account_rep_performance OWNER TO postgres;

--
-- TOC entry 859 (class 1259 OID 185172)
-- Name: vw_accounts_payable_aging; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_accounts_payable_aging AS
 SELECT s.supplier_name,
    si.invoice_number,
    si.invoice_date,
    si.due_date,
    si.grand_total AS invoice_amount,
    COALESCE(sum(spa.allocated_amount), (0)::numeric) AS paid_amount,
    (si.grand_total - COALESCE(sum(spa.allocated_amount), (0)::numeric)) AS outstanding_amount,
    (CURRENT_DATE - si.due_date) AS days_overdue,
        CASE
            WHEN (CURRENT_DATE <= si.due_date) THEN 'Current'::text
            WHEN ((CURRENT_DATE - si.due_date) <= 30) THEN '1-30 Days'::text
            WHEN ((CURRENT_DATE - si.due_date) <= 60) THEN '31-60 Days'::text
            WHEN ((CURRENT_DATE - si.due_date) <= 90) THEN '61-90 Days'::text
            ELSE '90+ Days'::text
        END AS aging_bucket
   FROM ((purchasing.suppliers s
     JOIN purchasing.supplier_invoices si ON ((si.supplier_id = s.supplier_id)))
     LEFT JOIN purchasing.supplier_payment_allocations spa ON ((spa.supplier_invoice_id = si.supplier_invoice_id)))
  WHERE ((si.status)::text = ANY ((ARRAY['APPROVED'::character varying, 'PARTIALLY_PAID'::character varying])::text[]))
  GROUP BY s.supplier_name, si.supplier_invoice_id, si.invoice_number, si.invoice_date, si.due_date, si.grand_total
 HAVING ((si.grand_total - COALESCE(sum(spa.allocated_amount), (0)::numeric)) > (0)::numeric);


ALTER VIEW reports.vw_accounts_payable_aging OWNER TO postgres;

--
-- TOC entry 871 (class 1259 OID 185232)
-- Name: vw_accounts_receivable_aging; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_accounts_receivable_aging AS
 SELECT (((c.first_name)::text || ' '::text) || (c.last_name)::text) AS customer_name,
    ar.transaction_date,
    ar.due_date,
    ar.original_amount,
    ar.outstanding_amount,
    (CURRENT_DATE - ar.due_date) AS days_overdue,
        CASE
            WHEN (CURRENT_DATE <= ar.due_date) THEN 'Current'::text
            WHEN ((CURRENT_DATE - ar.due_date) <= 30) THEN '1-30 Days'::text
            WHEN ((CURRENT_DATE - ar.due_date) <= 60) THEN '31-60 Days'::text
            WHEN ((CURRENT_DATE - ar.due_date) <= 90) THEN '61-90 Days'::text
            ELSE '90+ Days'::text
        END AS aging_bucket
   FROM (accounting.customer_receivables ar
     JOIN crm.customers c ON ((c.customer_id = ar.customer_id)))
  WHERE (((ar.status)::text = ANY ((ARRAY['OPEN'::character varying, 'PARTIALLY_PAID'::character varying])::text[])) AND (ar.outstanding_amount > (0)::numeric));


ALTER VIEW reports.vw_accounts_receivable_aging OWNER TO postgres;

--
-- TOC entry 889 (class 1259 OID 185333)
-- Name: vw_active_price_lists; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_active_price_lists AS
 SELECT pl.company_id,
    pl.price_list_id,
    pl.price_list_name,
    c.code AS currency_code,
    cs.segment_name AS customer_segment,
    sc.channel_name AS sales_channel,
    pl.start_date,
    pl.end_date,
    count(pr.price_id) AS product_count,
    pl.is_default,
    pl.is_active
   FROM ((((pricing.price_lists pl
     LEFT JOIN reference.currency_lookup c ON ((c.currency_id = pl.currency_id)))
     LEFT JOIN pricing.customer_segments cs ON ((cs.customer_segment_id = pl.customer_segment_id)))
     LEFT JOIN pricing.sales_channels sc ON ((sc.sales_channel_id = pl.sales_channel_id)))
     LEFT JOIN pricing.prices pr ON (((pr.price_list_id = pl.price_list_id) AND (pr.is_active = true))))
  WHERE ((pl.is_active = true) AND ((pl.end_date IS NULL) OR (pl.end_date >= CURRENT_DATE)))
  GROUP BY pl.company_id, pl.price_list_id, pl.price_list_name, c.code, cs.segment_name, sc.channel_name, pl.start_date, pl.end_date, pl.is_default, pl.is_active;


