--
-- TOC entry 851 (class 1259 OID 156710)
-- Name: vw_at_risk_customers; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_at_risk_customers AS
 SELECT c.customer_number,
    c.name AS display_name,
    c.email,
    COALESCE(cas.last_interaction_at, cas.last_case_at, cas.last_task_at) AS last_activity_at,
    (CURRENT_DATE - (COALESCE(cas.last_interaction_at, cas.last_case_at, cas.last_task_at))::date) AS days_since_last_activity,
    COALESCE(cas.order_count, 0) AS total_orders,
    COALESCE(cas.order_total, (0)::numeric) AS total_revenue,
    c.company_id
   FROM (public.customers c
     LEFT JOIN public.customer_account_summaries cas ON ((cas.customer_id = c.id)))
  WHERE ((COALESCE(cas.order_count, 0) > 0) AND ((CURRENT_DATE - (COALESCE(cas.last_interaction_at, cas.last_case_at, cas.last_task_at))::date) > 90))
  ORDER BY (CURRENT_DATE - (COALESCE(cas.last_interaction_at, cas.last_case_at, cas.last_task_at))::date) DESC
 LIMIT 100;


