--
-- TOC entry 878 (class 1259 OID 185267)
-- Name: vw_budget_vs_actual; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_budget_vs_actual AS
 SELECT eb.expense_budget_id,
    d.department_name,
    bu.business_unit_name,
    ecat.name AS category_name,
    eb.budget_amount AS total_budget,
    COALESCE(sum(ebp.actual_amount), (0)::numeric) AS total_actual,
    COALESCE(sum(ebp.committed_amount), (0)::numeric) AS total_committed,
    ((eb.budget_amount - COALESCE(sum(ebp.actual_amount), (0)::numeric)) - COALESCE(sum(ebp.committed_amount), (0)::numeric)) AS available,
        CASE
            WHEN (eb.budget_amount > (0)::numeric) THEN round(((COALESCE(sum(ebp.actual_amount), (0)::numeric) / eb.budget_amount) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS utilization_percent
   FROM ((((expenses.expense_budgets eb
     LEFT JOIN expenses.expense_budget_periods ebp ON ((ebp.expense_budget_id = eb.expense_budget_id)))
     LEFT JOIN organization.departments d ON ((d.department_id = eb.department_id)))
     LEFT JOIN organization.business_units bu ON ((bu.business_unit_id = eb.business_unit_id)))
     LEFT JOIN expenses.expense_categories ecat ON ((ecat.expense_category_id = eb.expense_category_id)))
  GROUP BY eb.expense_budget_id, d.department_name, bu.business_unit_name, ecat.name, eb.budget_amount
  ORDER BY
        CASE
            WHEN (eb.budget_amount > (0)::numeric) THEN round(((COALESCE(sum(ebp.actual_amount), (0)::numeric) / eb.budget_amount) * (100)::numeric), 2)
            ELSE (0)::numeric
        END DESC;


ALTER VIEW reports.vw_budget_vs_actual OWNER TO postgres;

