-- TOC entry 842 (class 1259 OID 156666)
-- Name: vw_case_resolution_time; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_case_resolution_time AS
 SELECT cg.company_id,
    reports.fn_case_type(sc.case_type) AS case_type,
    reports.fn_case_status(sc.status) AS case_status,
    reports.fn_case_priority(sc.priority) AS priority,
    count(*) AS total_cases,
    count(*) FILTER (WHERE ((sc.status = ANY (ARRAY[4, 5])) AND (sc.resolved_at IS NOT NULL))) AS resolved_cases,
    round(avg((EXTRACT(epoch FROM (COALESCE(sc.resolved_at, sc.closed_at) - sc.created_at)) / 3600.0)) FILTER (WHERE (COALESCE(sc.resolved_at, sc.closed_at) IS NOT NULL)), 2) AS avg_resolution_hours
   FROM (public.service_cases sc
     LEFT JOIN public.customers cg ON ((cg.id = sc.customer_id)))
  GROUP BY cg.company_id, sc.case_type, sc.status, sc.priority
  ORDER BY (round(avg((EXTRACT(epoch FROM (COALESCE(sc.resolved_at, sc.closed_at) - sc.created_at)) / 3600.0)) FILTER (WHERE (COALESCE(sc.resolved_at, sc.closed_at) IS NOT NULL)), 2)) DESC NULLS LAST;


ALTER VIEW reports.vw_case_resolution_time OWNER TO postgres;

