-- TOC entry 868 (class 1259 OID 185217)
-- Name: vw_cashier_performance; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_cashier_performance AS
 SELECT COALESCE(pp.display_name, (u.username)::character varying) AS cashier_name,
    count(DISTINCT ps.pos_shift_id) AS total_shifts,
    sum(pct.amount) FILTER (WHERE ((pct.transaction_type)::text = 'SALE'::text)) AS total_sales,
    sum(abs(ps.cash_difference)) AS total_cash_variance
   FROM (((pos.pos_shifts ps
     LEFT JOIN identity.users u ON ((u.user_id = ps.opened_by_user_id)))
     LEFT JOIN identity.persons pp ON ((pp.person_id = u.person_id)))
     LEFT JOIN pos.pos_cash_transactions pct ON ((pct.pos_shift_id = ps.pos_shift_id)))
  WHERE ((ps.opened_at >= (CURRENT_DATE - '30 days'::interval)) AND ((ps.status)::text = 'CLOSED'::text))
  GROUP BY ps.opened_by_user_id, pp.display_name, u.username;


ALTER VIEW reports.vw_cashier_performance OWNER TO postgres;

