 SELECT c.company_id,
    reports.fn_consent_type(cc.consent_type) AS consent_type,
    count(DISTINCT cc.customer_id) AS total_customers,
    count(DISTINCT
        CASE
            WHEN (cc.is_granted = true) THEN cc.customer_id
            ELSE NULL::uuid
        END) AS opted_in,
    count(DISTINCT
        CASE
            WHEN (cc.is_granted = false) THEN cc.customer_id
            ELSE NULL::uuid
        END) AS opted_out,
    round((((count(DISTINCT
        CASE
            WHEN (cc.is_granted = true) THEN cc.customer_id
            ELSE NULL::uuid
        END))::numeric / (NULLIF(count(DISTINCT cc.customer_id), 0))::numeric) * (100)::numeric), 2) AS opt_in_rate
   FROM (public.consent_records cc
     JOIN public.customers c ON ((c.id = cc.customer_id)))
  GROUP BY c.company_id, cc.consent_type
  ORDER BY (count(DISTINCT cc.customer_id)) DESC;


