--
-- TOC entry 865 (class 1259 OID 185202)
-- Name: vw_courier_performance; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_courier_performance AS
 SELECT sp.name AS provider_name,
    count(DISTINCT s.shipment_id) AS total_shipments,
    sum(
        CASE
            WHEN ((ssl.code)::text = 'DELIVERED'::text) THEN 1
            ELSE 0
        END) AS delivered_count,
    round((((sum(
        CASE
            WHEN ((ssl.code)::text = 'DELIVERED'::text) THEN 1
            ELSE 0
        END))::numeric / (NULLIF(count(DISTINCT s.shipment_id), 0))::numeric) * (100)::numeric), 2) AS delivery_success_rate,
    avg(EXTRACT(day FROM (s.delivered_at - s.shipped_at))) AS avg_delivery_days
   FROM ((shipping.shipping_providers sp
     LEFT JOIN shipping.shipments s ON ((s.shipping_provider_id = sp.shipping_provider_id)))
     LEFT JOIN shipping.shipment_status_lookup ssl ON ((ssl.shipment_status_id = s.shipment_status_id)))
  WHERE (s.shipped_at >= (CURRENT_DATE - '90 days'::interval))
  GROUP BY sp.shipping_provider_id, sp.name;


ALTER VIEW reports.vw_courier_performance OWNER TO postgres;

