    c.customer_number,
    reports.fn_customer_type(c.customer_type) AS customer_type,
    reports.fn_customer_status(c.status) AS customer_status,
    c.name AS display_name,
    c.email,
    c.phone_number,
    COALESCE(cas.order_total, (0)::numeric) AS total_revenue,
    COALESCE(cas.order_count, 0) AS total_orders,
    COALESCE(cas.interaction_count, 0) AS interaction_count,
    COALESCE(cas.case_count, 0) AS case_count,
    COALESCE(cas.task_count, 0) AS task_count,
    COALESCE(cas.referral_count, 0) AS referral_count,
    cas.last_interaction_at,
    cas.last_case_at,
    (COALESCE(cas.order_total, (0)::numeric) + COALESCE(cas.payment_total, (0)::numeric)) AS lifetime_value,
    c.created_at,
    c.company_id
   FROM (public.customers c
     LEFT JOIN public.customer_account_summaries cas ON ((cas.customer_id = c.id)))
  ORDER BY COALESCE(cas.order_total, (0)::numeric) DESC NULLS LAST;


