    count(DISTINCT cr.id) AS total_referrals,
    count(DISTINCT
        CASE
            WHEN (cr.status = 3) THEN cr.id
            ELSE NULL::uuid
        END) AS converted_referrals,
    round((((count(DISTINCT
        CASE
            WHEN (cr.status = 3) THEN cr.id
            ELSE NULL::uuid
        END))::numeric / (NULLIF(count(DISTINCT cr.id), 0))::numeric) * (100)::numeric), 2) AS conversion_rate,
