CREATE VIEW reports.vw_customer_relationship_map AS
 SELECT c1.company_id,
    reports.fn_relationship_type(cr.relationship_type) AS relationship_type,
    c1.customer_number AS source_code,
    c1.name AS source_name,
    c2.customer_number AS target_code,
    c2.name AS target_name,
    cr.created_at AS established_at
   FROM ((public.customer_relationships cr
     JOIN public.customers c1 ON ((c1.id = cr.customer_id)))
     JOIN public.customers c2 ON ((c2.id = cr.related_customer_id)));


ALTER VIEW reports.vw_customer_relationship_map OWNER TO postgres;

--
-- TOC entry 855 (class 1259 OID 156729)
-- Name: vw_customer_restrictions; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_customer_restrictions AS
 SELECT c.company_id,
    reports.fn_restriction_type(cr.restriction_type) AS restriction_type,
    reports.fn_severity(cr.severity) AS severity,
    count(DISTINCT cr.customer_id) AS restricted_customers,
    count(DISTINCT cr.customer_id) FILTER (WHERE ((cr.is_active = true) AND ((cr.active_to IS NULL) OR (cr.active_to >= CURRENT_DATE)))) AS active_restrictions,
    min(cr.created_at) AS first_applied_at,
    max(cr.created_at) AS last_applied_at
   FROM (public.customer_restrictions cr
     LEFT JOIN public.customers c ON ((c.id = cr.customer_id)))
  GROUP BY c.company_id, cr.restriction_type, cr.severity
  ORDER BY (count(DISTINCT cr.customer_id)) DESC;


ALTER VIEW reports.vw_customer_restrictions OWNER TO postgres;

--
-- TOC entry 840 (class 1259 OID 156657)
-- Name: vw_customer_segmentation; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_customer_segmentation AS
 SELECT cg.id AS group_id,
    cg.company_id,
    cg.name AS group_name,
    cg.is_active,
    count(DISTINCT cgm.customer_id) AS customer_count,
    sum(COALESCE(cas.order_total, (0)::numeric)) AS total_revenue,
    round(avg(COALESCE(cas.order_count, 0)), 2) AS avg_orders_per_customer
   FROM (((public.customer_groups cg
     LEFT JOIN public.customer_group_memberships cgm ON ((cgm.customer_group_id = cg.id)))
     LEFT JOIN public.customers c ON ((c.id = cgm.customer_id)))
     LEFT JOIN public.customer_account_summaries cas ON ((cas.customer_id = c.id)))
  WHERE (cg.is_active = true)
  GROUP BY cg.id, cg.company_id, cg.name, cg.is_active
  ORDER BY (count(DISTINCT cgm.customer_id)) DESC;


ALTER VIEW reports.vw_customer_segmentation OWNER TO postgres;

