CREATE VIEW reports.vw_customer_task_report AS
 SELECT company_id,
    reports.fn_task_type(type) AS task_type,
    reports.fn_task_status(status) AS task_status,
    count(*) AS task_count,
    count(*) FILTER (WHERE (status = 0)) AS pending_tasks,
    count(*) FILTER (WHERE (status = 2)) AS completed_tasks,
    count(*) FILTER (WHERE ((status = 0) AND (due_date < CURRENT_DATE))) AS overdue_tasks
   FROM public.customer_tasks ct
  GROUP BY company_id, type, status
  ORDER BY (count(*)) DESC;


ALTER VIEW reports.vw_customer_task_report OWNER TO postgres;

--
-- TOC entry 893 (class 1259 OID 185353)
-- Name: vw_dead_stock; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_dead_stock AS
 SELECT i.company_id,
    v.variant_code,
    v.variant_name,
    p.product_name,
    w.warehouse_name,
    sum(i.quantity_on_hand) AS total_stock,
    sum((i.quantity_on_hand * COALESCE(( SELECT icl.unit_cost
           FROM inventory.inventory_cost_layers icl
          WHERE (icl.variant_id = v.variant_id)
          ORDER BY icl.received_at DESC, icl.created_at DESC
         LIMIT 1), (0)::numeric))) AS stock_value,
    max(st.transaction_date) AS last_movement_date,
    (CURRENT_DATE - (max(st.transaction_date))::date) AS days_since_movement
   FROM ((((inventory.inventories i
     JOIN catalog.product_variants v ON ((v.variant_id = i.variant_id)))
     JOIN catalog.products p ON ((p.product_id = v.product_id)))
     JOIN inventory.warehouses w ON ((w.warehouse_id = i.warehouse_id)))
     LEFT JOIN inventory.stock_transactions st ON (((st.variant_id = v.variant_id) AND (st.warehouse_id = i.warehouse_id))))
  WHERE ((i.quantity_on_hand > (0)::numeric) AND (v.is_active = true))
  GROUP BY i.company_id, v.variant_id, v.variant_code, v.variant_name, p.product_name, w.warehouse_name
 HAVING ((max(st.transaction_date) IS NULL) OR ((CURRENT_DATE - (max(st.transaction_date))::date) > 90));


ALTER VIEW reports.vw_dead_stock OWNER TO postgres;

