--
-- TOC entry 886 (class 1259 OID 185307)
-- Name: vw_duplicate_expense_candidates; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_duplicate_expense_candidates AS
 SELECT expense_claim_item_id,
    expense_date,
    merchant_name,
    amount,
    reference_number,
    claim_number,
    potential_duplicates
   FROM ( SELECT eci.expense_claim_item_id,
            eci.expense_date,
            eci.merchant_name,
            eci.amount,
            eci.reference_number,
            ec.claim_number,
            count(*) OVER (PARTITION BY eci.expense_date, eci.merchant_name, eci.amount) AS potential_duplicates
           FROM (expenses.expense_claim_items eci
             JOIN expenses.expense_claims ec ON ((ec.expense_claim_id = eci.expense_claim_id)))
          WHERE (((ec.status)::text <> 'CANCELLED'::text) AND (eci.merchant_name IS NOT NULL) AND (eci.amount > (0)::numeric))) sub
  WHERE (potential_duplicates > 1)
  ORDER BY expense_date DESC;


ALTER VIEW reports.vw_duplicate_expense_candidates OWNER TO postgres;

--
-- TOC entry 832 (class 1259 OID 156618)
