CREATE VIEW reports.vw_employee_assignment_distribution AS
 SELECT ea.company_id,
    c.name AS company_name,
    bu.name AS business_unit_name,
    d.name AS department_name,
    s.name AS store_name,
    w.name AS warehouse_name,
    count(DISTINCT ea.employee_id) AS employee_count
   FROM (((((public.employee_assignments ea
     JOIN public.companies c ON ((c.id = ea.company_id)))
     LEFT JOIN public.business_units bu ON ((bu.id = ea.business_unit_id)))
     LEFT JOIN public.departments d ON ((d.id = ea.department_id)))
     LEFT JOIN public.stores s ON ((s.id = ea.store_id)))
     LEFT JOIN public.warehouses w ON ((w.id = ea.warehouse_id)))
  WHERE ((ea.effective_to IS NULL) OR (ea.effective_to >= CURRENT_DATE))
  GROUP BY ea.company_id, c.name, bu.name, d.name, s.name, w.name
  ORDER BY (count(DISTINCT ea.employee_id)) DESC;


