--
-- TOC entry 884 (class 1259 OID 185297)
-- Name: vw_expense_aging; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_expense_aging AS
 SELECT expense_claim_id,
    claim_number,
    claim_date,
    total_amount,
    status,
    (CURRENT_DATE - claim_date) AS age_days,
        CASE
            WHEN ((CURRENT_DATE - claim_date) <= 7) THEN '0-7 Days'::text
            WHEN ((CURRENT_DATE - claim_date) <= 30) THEN '8-30 Days'::text
            WHEN ((CURRENT_DATE - claim_date) <= 60) THEN '31-60 Days'::text
            WHEN ((CURRENT_DATE - claim_date) <= 90) THEN '61-90 Days'::text
            ELSE '90+ Days'::text
        END AS aging_bucket
   FROM expenses.expense_claims ec
  WHERE ((status)::text = ANY ((ARRAY['SUBMITTED'::character varying, 'UNDER_REVIEW'::character varying, 'APPROVED'::character varying, 'PARTIALLY_APPROVED'::character varying, 'PAYMENT_PENDING'::character varying])::text[]))
  ORDER BY (CURRENT_DATE - claim_date) DESC;


ALTER VIEW reports.vw_expense_aging OWNER TO postgres;

--
-- TOC entry 873 (class 1259 OID 185242)
-- Name: vw_expense_by_category; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_expense_by_category AS
 SELECT ecat.code AS category_code,
    ecat.name AS category_name,
    pcat.name AS parent_category_name,
    count(DISTINCT eci.expense_claim_item_id) AS transaction_count,
    sum(eci.amount) AS total_amount,
    sum(eci.tax_amount) AS total_tax,
    sum(eci.base_amount) AS total_base_amount,
    avg(eci.amount) AS avg_amount
   FROM (((expenses.expense_claim_items eci
     JOIN expenses.expense_categories ecat ON ((ecat.expense_category_id = eci.expense_category_id)))
     LEFT JOIN expenses.expense_categories pcat ON ((pcat.expense_category_id = ecat.parent_category_id)))
     JOIN expenses.expense_claims ec ON ((ec.expense_claim_id = eci.expense_claim_id)))
  WHERE ((ec.status)::text <> ALL ((ARRAY['DRAFT'::character varying, 'CANCELLED'::character varying])::text[]))
  GROUP BY ecat.code, ecat.name, pcat.name
  ORDER BY (sum(eci.amount)) DESC;


ALTER VIEW reports.vw_expense_by_category OWNER TO postgres;

--
-- TOC entry 874 (class 1259 OID 185247)
-- Name: vw_expense_by_department; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_expense_by_department AS
 SELECT d.department_name,
    bu.business_unit_name,
    count(DISTINCT ec.expense_claim_id) AS claim_count,
    sum(ec.total_amount) AS total_amount,
    sum(ec.approved_amount) AS approved_amount,
    sum(ec.reimbursed_amount) AS reimbursed_amount,
    avg(ec.total_amount) AS avg_claim_amount
   FROM ((expenses.expense_claims ec
     LEFT JOIN organization.departments d ON ((d.department_id = ec.department_id)))
     LEFT JOIN organization.business_units bu ON ((bu.business_unit_id = ec.business_unit_id)))
  WHERE ((ec.status)::text <> ALL ((ARRAY['DRAFT'::character varying, 'CANCELLED'::character varying])::text[]))
  GROUP BY d.department_name, bu.business_unit_name
  ORDER BY (sum(ec.total_amount)) DESC;


ALTER VIEW reports.vw_expense_by_department OWNER TO postgres;

