--
-- TOC entry 872 (class 1259 OID 185237)
-- Name: vw_expense_claim_summary; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_expense_claim_summary AS
 SELECT ec.expense_claim_id,
    ec.claim_number,
    ec.claim_date,
    ec.status,
    ec.total_amount,
    ec.approved_amount,
    ec.rejected_amount,
    ec.reimbursed_amount,
    ec.currency_id,
    c.code AS currency_code,
    d.department_name,
    bu.business_unit_name,
    count(DISTINCT eci.expense_claim_item_id) AS item_count,
    ec.submitted_at,
    ec.approved_at,
    ec.paid_at,
    ec.created_at
   FROM ((((expenses.expense_claims ec
     LEFT JOIN reference.currency_lookup c ON ((c.currency_id = ec.currency_id)))
     LEFT JOIN organization.departments d ON ((d.department_id = ec.department_id)))
     LEFT JOIN organization.business_units bu ON ((bu.business_unit_id = ec.business_unit_id)))
     LEFT JOIN expenses.expense_claim_items eci ON ((eci.expense_claim_id = ec.expense_claim_id)))
  GROUP BY ec.expense_claim_id, ec.claim_number, ec.claim_date, ec.status, ec.total_amount, ec.approved_amount, ec.rejected_amount, ec.reimbursed_amount, ec.currency_id, c.code, d.department_name, bu.business_unit_name, ec.submitted_at, ec.approved_at, ec.paid_at, ec.created_at
  ORDER BY ec.claim_date DESC;


ALTER VIEW reports.vw_expense_claim_summary OWNER TO postgres;

--
-- TOC entry 881 (class 1259 OID 185282)
-- Name: vw_expense_trend_monthly; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_expense_trend_monthly AS
 SELECT date_trunc('month'::text, (claim_date)::timestamp with time zone) AS expense_month,
    count(DISTINCT expense_claim_id) AS claim_count,
    sum(total_amount) AS total_amount,
    sum(approved_amount) AS approved_amount,
    avg(total_amount) AS avg_claim_amount
   FROM expenses.expense_claims ec
  WHERE (((status)::text <> ALL ((ARRAY['DRAFT'::character varying, 'CANCELLED'::character varying])::text[])) AND (claim_date >= (CURRENT_DATE - '1 year'::interval)))
  GROUP BY (date_trunc('month'::text, (claim_date)::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, (claim_date)::timestamp with time zone)) DESC;


ALTER VIEW reports.vw_expense_trend_monthly OWNER TO postgres;

--
-- TOC entry 825 (class 1259 OID 156584)
-- Name: vw_failed_login_analysis; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_failed_login_analysis AS
 SELECT u.id AS user_id,
    u.username,
    u.email,
    reports.fn_user_status(u.status) AS account_status,
    count(*) AS failed_attempts,
    min(la.created_at) AS first_failed_at,
    max(la.created_at) AS last_failed_at,
    count(DISTINCT la.ip_address) AS unique_ips
   FROM (public.login_attempts la
     JOIN public.user_accounts u ON ((u.id = la.user_id)))
  WHERE ((la.success = false) AND (la.created_at >= (CURRENT_DATE - '7 days'::interval)))
  GROUP BY u.id, u.username, u.email, u.status
 HAVING (count(*) >= 5)
  ORDER BY (count(*)) DESC;


ALTER VIEW reports.vw_failed_login_analysis OWNER TO postgres;

