--

CREATE VIEW reports.vw_gateway_fees AS
 SELECT date(pt.processed_at) AS settlement_date,
    pg.name AS payment_gateway,
    sum(pt.amount) AS total_gross,
    (0)::numeric AS total_fees,
    sum(pt.amount) AS total_net
   FROM ((payments.payment_transactions pt
     JOIN payments.payments p ON ((p.payment_id = pt.payment_id)))
     JOIN payments.payment_gateways pg ON ((pg.payment_gateway_id = p.payment_gateway_id)))
  WHERE (pt.processed_at >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY (date(pt.processed_at)), pg.name;


ALTER VIEW reports.vw_gateway_fees OWNER TO postgres;

