--
-- TOC entry 888 (class 1259 OID 185328)
-- Name: vw_low_content_products; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_low_content_products AS
 SELECT company_id,
    product_id,
    product_code,
    product_name,
        CASE
            WHEN ((description IS NULL) OR (length(description) < 50)) THEN true
            ELSE false
        END AS missing_description,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM catalog.product_media pi
              WHERE ((pi.product_id = p.product_id) AND (pi.is_active = true))))) THEN true
            ELSE false
        END AS missing_images,
    created_at
   FROM catalog.products p
  WHERE ((is_active = true) AND ((description IS NULL) OR (length(description) < 50) OR (NOT (EXISTS ( SELECT 1
           FROM catalog.product_media pi
          WHERE ((pi.product_id = p.product_id) AND (pi.is_active = true)))))))
  ORDER BY created_at DESC;


