--
-- TOC entry 892 (class 1259 OID 185348)
-- Name: vw_low_stock_alert; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_low_stock_alert AS
 SELECT i.company_id,
    v.variant_code,
    v.variant_name,
    p.product_name,
    w.warehouse_name,
    i.quantity_on_hand,
    i.quantity_reserved,
    (i.quantity_on_hand - i.quantity_reserved) AS available_stock,
    i.reorder_level,
        CASE
            WHEN ((i.quantity_on_hand - i.quantity_reserved) <= i.reorder_level) THEN 'CRITICAL'::text
            ELSE 'LOW'::text
        END AS stock_status
   FROM (((inventory.inventories i
     JOIN catalog.product_variants v ON ((v.variant_id = i.variant_id)))
     JOIN catalog.products p ON ((p.product_id = v.product_id)))
     JOIN inventory.warehouses w ON ((w.warehouse_id = i.warehouse_id)))
  WHERE (((i.quantity_on_hand - i.quantity_reserved) <= i.reorder_level) AND (i.reorder_level > (0)::numeric) AND (v.is_active = true))
  ORDER BY (i.quantity_on_hand - i.quantity_reserved);


ALTER VIEW reports.vw_low_stock_alert OWNER TO postgres;

--
-- TOC entry 826 (class 1259 OID 156589)
-- Name: vw_mfa_adoption; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_mfa_adoption AS
 SELECT count(DISTINCT u.id) AS total_users,
    count(DISTINCT
        CASE
            WHEN (mm.id IS NOT NULL) THEN u.id
            ELSE NULL::uuid
        END) AS users_with_mfa,
    count(DISTINCT
        CASE
            WHEN (mm.id IS NULL) THEN u.id
            ELSE NULL::uuid
        END) AS users_without_mfa,
    round((((count(DISTINCT
        CASE
            WHEN (mm.id IS NOT NULL) THEN u.id
            ELSE NULL::uuid
        END))::numeric / (NULLIF(count(DISTINCT u.id), 0))::numeric) * (100)::numeric), 2) AS mfa_adoption_percent
   FROM (public.user_accounts u
     LEFT JOIN public.mfa_methods mm ON (((mm.user_id = u.id) AND (mm.is_enabled = true))))
  WHERE (u.status = 1);


ALTER VIEW reports.vw_mfa_adoption OWNER TO postgres;

