--
-- TOC entry 862 (class 1259 OID 185187)
-- Name: vw_payment_summary; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_payment_summary AS
 SELECT date(p.created_at) AS payment_date,
    pm.name AS payment_method,
    pg.name AS payment_gateway,
    count(DISTINCT p.payment_id) AS total_payments,
    sum(p.amount) AS total_amount,
    sum(p.captured_amount) AS total_captured,
    sum(
        CASE
            WHEN ((psl.code)::text = 'COMPLETED'::text) THEN 1
            ELSE 0
        END) AS completed_count,
    sum(
        CASE
            WHEN ((psl.code)::text = 'FAILED'::text) THEN 1
            ELSE 0
        END) AS failed_count
   FROM (((payments.payments p
     JOIN payments.payment_methods pm ON ((pm.payment_method_id = p.payment_method_id)))
     LEFT JOIN payments.payment_gateways pg ON ((pg.payment_gateway_id = p.payment_gateway_id)))
     JOIN payments.payment_status_lookup psl ON ((psl.payment_status_id = p.payment_status_id)))
  WHERE (p.created_at >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY (date(p.created_at)), pm.name, pg.name
  ORDER BY (date(p.created_at)) DESC;


ALTER VIEW reports.vw_payment_summary OWNER TO postgres;

