--
-- TOC entry 877 (class 1259 OID 185262)
-- Name: vw_petty_cash_balance; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_petty_cash_balance AS
 SELECT pca.petty_cash_account_id,
    pca.opening_balance,
    pca.current_balance,
    pca.maximum_balance,
    pca.status,
    bu.business_unit_name,
    c.code AS currency_code,
    ( SELECT sum(
                CASE
                    WHEN ((pct.transaction_type)::text = ANY ((ARRAY['CASH_IN'::character varying, 'REPLENISHMENT'::character varying, 'OPENING_BALANCE'::character varying])::text[])) THEN pct.amount
                    ELSE (0)::numeric
                END) AS sum
           FROM expenses.petty_cash_transactions pct
          WHERE (pct.petty_cash_account_id = pca.petty_cash_account_id)) AS total_in,
    ( SELECT sum(
                CASE
                    WHEN ((pct.transaction_type)::text = ANY ((ARRAY['EXPENSE'::character varying, 'CASH_OUT'::character varying])::text[])) THEN abs(pct.amount)
                    ELSE (0)::numeric
                END) AS sum
           FROM expenses.petty_cash_transactions pct
          WHERE (pct.petty_cash_account_id = pca.petty_cash_account_id)) AS total_out
   FROM ((expenses.petty_cash_accounts pca
     LEFT JOIN organization.business_units bu ON ((bu.business_unit_id = pca.business_unit_id)))
     LEFT JOIN reference.currency_lookup c ON ((c.currency_id = pca.currency_id)));


ALTER VIEW reports.vw_petty_cash_balance OWNER TO postgres;

