-- TOC entry 887 (class 1259 OID 185323)
-- Name: vw_product_master; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_product_master AS
 SELECT p.company_id,
    p.product_id,
    p.product_code,
    p.product_name,
    COALESCE(( SELECT pc.category_name
           FROM (catalog.product_categories pcat
             JOIN catalog.categories pc ON ((pc.category_id = pcat.category_id)))
          WHERE ((pcat.product_id = p.product_id) AND (pcat.is_primary = true))
          ORDER BY pcat.sort_order, pcat.product_category_id
         LIMIT 1), ( SELECT pc.category_name
           FROM (catalog.product_categories pcat
             JOIN catalog.categories pc ON ((pc.category_id = pcat.category_id)))
          WHERE (pcat.product_id = p.product_id)
          ORDER BY pcat.sort_order, pcat.product_category_id
         LIMIT 1)) AS category_name,
    b.brand_name,
    count(DISTINCT v.variant_id) AS variant_count,
    sum(COALESCE(i.quantity_on_hand, (0)::numeric)) AS total_stock,
    min(pr.unit_price) AS min_price,
    max(pr.unit_price) AS max_price,
    p.is_active,
    p.created_at
   FROM ((((catalog.products p
     LEFT JOIN catalog.brands b ON ((b.brand_id = p.brand_id)))
     LEFT JOIN catalog.product_variants v ON ((v.product_id = p.product_id)))
     LEFT JOIN inventory.inventories i ON ((i.variant_id = v.variant_id)))
     LEFT JOIN pricing.prices pr ON (((pr.variant_id = v.variant_id) AND (pr.is_active = true))))
  GROUP BY p.company_id, p.product_id, p.product_code, p.product_name, b.brand_name, p.is_active, p.created_at
  ORDER BY p.product_name;


ALTER VIEW reports.vw_product_master OWNER TO postgres;

