--
-- TOC entry 861 (class 1259 OID 185182)
-- Name: vw_sales_by_product_30days; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_sales_by_product_30days AS
 SELECT p.product_name,
    COALESCE(( SELECT pc.category_name
           FROM (catalog.product_categories pcat
             JOIN catalog.categories pc ON ((pc.category_id = pcat.category_id)))
          WHERE ((pcat.product_id = p.product_id) AND (pcat.is_primary = true))
          ORDER BY pcat.sort_order, pcat.product_category_id
         LIMIT 1), NULL::character varying) AS category_name,
    sum(oi.quantity) AS total_quantity_sold,
    sum(oi.final_amount) AS total_revenue,
    sum((oi.cost_snapshot * oi.quantity)) AS total_cogs,
    sum((oi.final_amount - (oi.cost_snapshot * oi.quantity))) AS gross_profit
   FROM (((sales.order_items oi
     JOIN catalog.product_variants v ON ((v.variant_id = oi.variant_id)))
     JOIN catalog.products p ON ((p.product_id = v.product_id)))
     JOIN sales.orders o ON ((o.order_id = oi.order_id)))
  WHERE (o.order_date >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY p.product_name, p.product_id
  ORDER BY (sum(oi.final_amount)) DESC
 LIMIT 100;


ALTER VIEW reports.vw_sales_by_product_30days OWNER TO postgres;

--
-- TOC entry 860 (class 1259 OID 185177)
-- Name: vw_sales_order_summary; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_sales_order_summary AS
 SELECT date(o.order_date) AS order_date,
    count(DISTINCT o.order_id) AS total_orders,
    sum(o.grand_total) AS total_revenue,
    avg(o.grand_total) AS avg_order_value,
    count(DISTINCT o.customer_id) AS unique_customers,
    sc.channel_name AS sales_channel
   FROM (sales.orders o
     LEFT JOIN pricing.sales_channels sc ON ((sc.sales_channel_id = o.sales_channel_id)))
  WHERE (o.order_date >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY (date(o.order_date)), sc.channel_name
  ORDER BY (date(o.order_date)) DESC;


ALTER VIEW reports.vw_sales_order_summary OWNER TO postgres;

