--
-- TOC entry 864 (class 1259 OID 185197)
-- Name: vw_shipment_summary; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_shipment_summary AS
 SELECT date(s.shipped_at) AS shipment_date,
    sp.name AS shipping_provider,
    count(DISTINCT s.shipment_id) AS total_shipments,
    sum(s.shipping_cost) AS total_shipping_cost,
    sum(
        CASE
            WHEN ((ssl.code)::text = 'DELIVERED'::text) THEN 1
            ELSE 0
        END) AS delivered_count,
    sum(
        CASE
            WHEN ((ssl.code)::text = 'DELIVERY_FAILED'::text) THEN 1
            ELSE 0
        END) AS failed_count
   FROM ((shipping.shipments s
     JOIN shipping.shipping_providers sp ON ((sp.shipping_provider_id = s.shipping_provider_id)))
     JOIN shipping.shipment_status_lookup ssl ON ((ssl.shipment_status_id = s.shipment_status_id)))
  WHERE (s.shipped_at >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY (date(s.shipped_at)), sp.name
  ORDER BY (date(s.shipped_at)) DESC;


ALTER VIEW reports.vw_shipment_summary OWNER TO postgres;

--
