--

CREATE VIEW reports.vw_stock_summary_by_warehouse AS
 SELECT w.company_id,
    w.warehouse_id,
    w.warehouse_code,
    w.warehouse_name,
    w.warehouse_type,
    count(DISTINCT i.variant_id) AS unique_products,
    sum(i.quantity_on_hand) AS total_on_hand,
    sum(i.quantity_reserved) AS total_reserved,
    sum((i.quantity_on_hand - i.quantity_reserved)) AS total_available,
    sum((i.quantity_on_hand * COALESCE(( SELECT icl.unit_cost
           FROM inventory.inventory_cost_layers icl
          WHERE (icl.variant_id = i.variant_id)
          ORDER BY icl.received_at DESC, icl.created_at DESC
         LIMIT 1), (0)::numeric))) AS total_inventory_value
   FROM (inventory.warehouses w
     LEFT JOIN inventory.inventories i ON ((i.warehouse_id = w.warehouse_id)))
  WHERE (w.is_active = true)
  GROUP BY w.company_id, w.warehouse_id, w.warehouse_code, w.warehouse_name, w.warehouse_type;


ALTER VIEW reports.vw_stock_summary_by_warehouse OWNER TO postgres;

