--
-- TOC entry 869 (class 1259 OID 185222)
-- Name: vw_trial_balance; Type: VIEW; Schema: reports; Owner: postgres
--

CREATE VIEW reports.vw_trial_balance AS
 SELECT a.account_code,
    a.account_name,
    at.code AS account_type,
    sum(jel.debit_amount) AS total_debit,
    sum(jel.credit_amount) AS total_credit,
        CASE
            WHEN ((a.normal_balance)::text = 'DEBIT'::text) THEN (sum(jel.debit_amount) - sum(jel.credit_amount))
            ELSE (sum(jel.credit_amount) - sum(jel.debit_amount))
        END AS balance
   FROM (((accounting.journal_entry_lines jel
     JOIN accounting.journal_entries je ON ((je.journal_entry_id = jel.journal_entry_id)))
     JOIN accounting.accounts a ON ((a.account_id = jel.account_id)))
     JOIN accounting.account_types at ON ((at.account_type_id = a.account_type_id)))
  WHERE ((je.status)::text = 'POSTED'::text)
  GROUP BY a.account_code, a.account_name, at.code, a.normal_balance
  ORDER BY a.account_code;


ALTER VIEW reports.vw_trial_balance OWNER TO postgres;

