     LEFT JOIN public.mfa_methods mm ON (((mm.user_id = u.id) AND (mm.is_enabled = true))))
  GROUP BY u.id, u.username, u.email, p.first_name, p.last_name, u.status, u.last_login_at, u.created_at
  ORDER BY u.created_at DESC;


