--

CREATE VIEW reports.vw_user_status_transitions AS
 SELECT al.id AS audit_log_id,
    al.created_at AS transition_date,
    u.username,
    u.email,
    "substring"(al.old_values, 'status=([^, ;]+)'::text) AS old_status,
    "substring"(al.new_values, 'status=([^, ;]+)'::text) AS new_status,
    al.ip_address,
    al.company_id
   FROM (public.audit_logs al
     LEFT JOIN public.user_accounts u ON ((u.id = al.user_id)))
  WHERE ((al.entity_type = 'UserAccount'::text) AND (al.action = 1) AND ("substring"(al.old_values, 'status=([^, ;]+)'::text) IS DISTINCT FROM "substring"(al.new_values, 'status=([^, ;]+)'::text)))
  ORDER BY al.created_at DESC;


