CREATE VIEW reports.vw_warehouse_utilization AS
 SELECT iw.id AS warehouse_id,
    bw.company_id,
    iw.warehouse_code,
    iw.name AS warehouse_name,
    reports.fn_warehouse_type(iw.type) AS warehouse_type,
    iw.is_active,
    count(DISTINCT wl.id) AS location_count,
    count(DISTINCT i.product_variant_id) AS unique_skus,
    COALESCE(sum(i.quantity_on_hand), (0)::numeric) AS total_units_on_hand,
    count(DISTINCT ((wl.location_code || ':'::text) || i.product_variant_id)) FILTER (WHERE (i.quantity_on_hand <= COALESCE(i.reorder_level, (0)::numeric))) AS low_stock_skus
   FROM (((public.inventory_warehouses iw
     LEFT JOIN public.business_units bw ON ((bw.id = iw.business_unit_id)))
     LEFT JOIN public.warehouse_locations wl ON (((wl.warehouse_id = iw.id) AND (wl.is_active = true))))
     LEFT JOIN public.inventories i ON ((i.location_id = wl.id)))
  WHERE (iw.is_active = true)
  GROUP BY iw.id, bw.company_id, iw.warehouse_code, iw.name, iw.type, iw.is_active
  ORDER BY COALESCE(sum(i.quantity_on_hand), (0)::numeric) DESC;


