--
-- TOC entry 14093 (class 2618 OID 156616)
-- Name: vw_branch_operations _RETURN; Type: RULE; Schema: reports; Owner: postgres
--

CREATE OR REPLACE VIEW reports.vw_branch_operations AS
 SELECT b.id AS branch_id,
    b.company_id,
    b.code AS branch_code,
    b.name AS branch_name,
    reports.fn_branch_type(b.branch_type) AS branch_type,
    b.city,
    b.country,
    b.is_active,
    b.created_at,
    count(DISTINCT s.id) AS store_count,
    count(DISTINCT w.id) AS warehouse_count,
    count(DISTINCT ea.id) AS employee_count
   FROM (((public.branches b
     LEFT JOIN public.stores s ON (((s.branch_id = b.id) AND (s.is_active = true))))
     LEFT JOIN public.warehouses w ON (((w.branch_id = b.id) AND (w.is_active = true))))
     LEFT JOIN public.employee_assignments ea ON (((ea.branch_id = b.id) AND ((ea.effective_to IS NULL) OR (ea.effective_to >= CURRENT_DATE)))))
  WHERE (b.is_active = true)
  GROUP BY b.id, b.code, b.name, b.branch_type, b.city, b.country, b.is_active, b.created_at
  ORDER BY (count(DISTINCT ea.id)) DESC;


--
-- TOC entry 14091 (class 2618 OID 156606)
-- Name: vw_business_unit_hierarchy _RETURN; Type: RULE; Schema: reports; Owner: postgres
--

CREATE OR REPLACE VIEW reports.vw_business_unit_hierarchy AS
 SELECT bu.id AS business_unit_id,
    bu.company_id,
    c.name AS company_name,
    bu.code AS business_unit_code,
    bu.name AS business_unit_name,
    bu.is_active,
    bu.created_at,
    bu.updated_at,
    count(DISTINCT d.id) AS department_count
   FROM ((public.business_units bu
     JOIN public.companies c ON ((c.id = bu.company_id)))
     LEFT JOIN public.departments d ON (((d.business_unit_id = bu.id) AND (d.is_active = true))))
  GROUP BY bu.id, c.name, bu.code, bu.name, bu.is_active, bu.created_at, bu.updated_at
  ORDER BY c.name, bu.name;


--
-- TOC entry 14092 (class 2618 OID 156611)
-- Name: vw_department_headcount _RETURN; Type: RULE; Schema: reports; Owner: postgres
--

CREATE OR REPLACE VIEW reports.vw_department_headcount AS
 SELECT d.id AS department_id,
    d.company_id,
    d.code AS department_code,
    d.name AS department_name,
    bu.name AS business_unit_name,
    d.is_active,
    count(DISTINCT ea.employee_id) AS employee_count
   FROM ((public.departments d
     LEFT JOIN public.business_units bu ON ((bu.id = d.business_unit_id)))
     LEFT JOIN public.employee_assignments ea ON (((ea.department_id = d.id) AND ((ea.effective_to IS NULL) OR (ea.effective_to >= CURRENT_DATE)))))
  WHERE (d.is_active = true)
  GROUP BY d.id, d.code, d.name, bu.name, d.is_active
  ORDER BY (count(DISTINCT ea.employee_id)) DESC;


